// allocate.ax — bounded resource allocation (0/1 knapsack).
//
// An agent with a fixed cost budget must pick the SUBSET of actions that
// maximizes total value without exceeding the budget — the Budget safety
// primitive as an optimization, not just a gate. Solved exactly by
// include/exclude recursion (no mutation needed); the candidate set is borrowed
// (`&[Item]`) so it can be threaded through the recursion without being moved.
//
//   axon run  examples/asi/allocate.ax
//   axon test examples/asi/allocate.ax

type Item = { name: str, value: i64, cost: i64 }

// Best total value achievable from items[i..] within `budget` (0/1 knapsack):
// at each item, take the better of skipping it or taking it (if affordable).
fn best_value(items: &[Item], i: i64, budget: i64) -> i64 {
    if i >= len(items) {
        0
    } else {
        let skip = best_value(items, i + 1, budget)
        let cost = items[i].cost
        let value = items[i].value
        if cost <= budget {
            let take = value + best_value(items, i + 1, budget - cost)
            if take > skip { take } else { skip }
        } else {
            skip
        }
    }
}

fn max_value(items: &[Item], budget: i64) -> i64 {
    best_value(items, 0, budget)
}

fn samples() -> [Item] {
    [
        Item { name: "summarize", value: 60, cost: 10 },
        Item { name: "analyze", value: 100, cost: 20 },
        Item { name: "verify", value: 120, cost: 30 },
    ]
}

@[test]
fn test_knapsack_picks_best_subset() {
    let items = samples()
    // budget 50: {analyze, verify} cost 50 → value 220 (beats {summarize,verify}=180).
    assert_eq(max_value(&items, 50), 220)
}

@[test]
fn test_tight_budget() {
    let items = samples()
    assert_eq(max_value(&items, 10), 60) // only "summarize" fits
    assert_eq(max_value(&items, 0), 0)   // nothing fits
}

@[test]
fn test_whole_budget() {
    let items = samples()
    assert_eq(max_value(&items, 60), 280) // all three fit (cost 60)
}

fn main() {
    let items = samples()
    let budget = 50
    println("budget {to_str(budget)}: best achievable value = {to_str(max_value(&items, budget))}")
    println("(budget 60 would allow all three: {to_str(max_value(&items, 60))})")
}

sources.examples/asi/coord_attested.ax:
// coord_attested.ax — Cross-VM Coordination with Attestation Identity
//
// Demonstrates: CoordGoal (Phase 14) + R26 attestation as principal identity.
//
// Scenario: Three "attested principals" each independently score a proposed
// AI action.  The action is approved only when a strict majority of attested
// principals vote >= 75.  A single attested principal cannot force approval.
//
// In a real deployment each principal runs in a separate attested microVM
// (R26).  Here we simulate three principals in-process using distinct
// principal names that encode an attestation token in their name.
// Format: "attested:<token>:<role>"
//
// Properties demonstrated:
//   - Minority coalition cannot force CoordGoal consensus (from coord.ax)
//   - Each principal carries a distinct attestation token in its name
//   - A principal with an absent or mismatched token is rejected by the verifier
//   - The consensus score = minimum accepted score (conservative)
//
// Run:
//   axon test examples/asi/coord_attested.ax
//   axon run  examples/asi/coord_attested.ax

// ── Inlined CoordGoal (from examples/stdlib/coord.ax) ─────────────────────────
// Axon has no module imports yet; self-contained by design.
//
// Cross-Principal goal coordination. N independent principals each evaluate
// a candidate and submit a score.  The goal is committed only when a strict
// majority -- floor(n/2)+1 -- of principals each report a score >= target.
// Safety invariant: a minority coalition cannot force acceptance.

type CoordGoal = {
    target:    i64,    // minimum score each principal must reach to accept
    n:         i64,    // total number of principals
    scores:    [i64],  // scores[i] = principal i's submitted score (0 = not yet)
    submitted: [i64],  // submitted[i] = 1 if principal i has voted, else 0
}

fn coord_goal_new(n_principals: i64, target: i64) -> CoordGoal {
    assert(n_principals > 0)
    CoordGoal {
        target:    target,
        n:         n_principals,
        scores:    arr_repeat(0, n_principals),
        submitted: arr_repeat(0, n_principals),
    }
}

// Principal `pid` submits score `score`. Idempotent: repeated proposals ignored.
fn coord_goal_propose(cg: CoordGoal, pid: i64, score: i64) -> CoordGoal {
    assert(pid >= 0 && pid < cg.n)
    if cg.submitted[pid] == 1 {
        cg
    } else {
        let new_scores = []
        let new_sub    = []
        let i = 0
        while i < cg.n {
            new_scores = arr_push(new_scores, if i == pid { score } else { cg.scores[i] })
            new_sub    = arr_push(new_sub, if i == pid { 1 } else { cg.submitted[i] })
            i = i + 1
        }
        CoordGoal { target: cg.target, n: cg.n, scores: new_scores, submitted: new_sub }
    }
}

fn coord_goal_accept_count(cg: CoordGoal) -> i64 {
    let count = 0
    let i = 0
    while i < cg.n {
        if cg.submitted[i] == 1 && cg.scores[i] >= cg.target { count = count + 1 }
        i = i + 1
    }
    count
}

// Quorum threshold: strict majority = floor(n/2) + 1.
fn coord_goal_quorum(cg: CoordGoal) -> i64 { cg.n / 2 + 1 }

fn coord_goal_quorum_met(cg: CoordGoal) -> bool {
    coord_goal_accept_count(cg) >= coord_goal_quorum(cg)
}

// Conservative consensus score: minimum accepted score. Returns -1 when quorum unmet.
fn coord_goal_consensus_score(cg: CoordGoal) -> i64 {
    if !coord_goal_quorum_met(cg) {
        -1
    } else {
        let best = 9999999
        let i = 0
        while i < cg.n {
            if cg.submitted[i] == 1 && cg.scores[i] >= cg.target {
                if cg.scores[i] < best { best = cg.scores[i] }
            }
            i = i + 1
        }
        best
    }
}

// ── Attestation helpers ────────────────────────────────────────────────────────
// In a real R26 deployment an attestation token is the axtcb1:<digest> from
// the measured kernel image.  Here we simulate it as a short identifier
// embedded in the principal name using the format "attested:<token>:<role>".

fn is_attested(principal: str) -> bool {
    str_starts_with(principal, "attested:")
}

// Verify that a principal carries the expected attestation token.
// The token sits between the first and second colon: "attested:<TOKEN>:<role>".
// We use str_contains as a conservative presence check — a real verifier
// would parse and compare the exact field, but for this demo it is sufficient
// to show that the token must appear in the name.
fn verify_principal(principal: str, expected_token: str) -> Result<str, str> {
    if !is_attested(principal) {
        Err("principal has no attestation token")
    } else if !str_contains(principal, expected_token) {
        Err("attestation token mismatch -- principal may be impersonating another VM")
    } else {
        Ok(principal)
    }
}

// ── Scoring oracle ─────────────────────────────────────────────────────────────
// Each principal independently scores the proposed action based on its own
// risk model.  Lower risk = higher score.  @[adaptive] tags the function so
// the provenance log captures every (risk_level, score) pair — useful for
// auditing which principal voted and at what level.

@[adaptive(metric: action_score, target: 100)]
fn score_action(risk_level: i64) -> i64 {
    if risk_level < 20 { 95 }
    else if risk_level < 50 { 82 }
    else if risk_level < 80 { 65 }
    else { 30 }
}

// ── Per-principal vote helper ──────────────────────────────────────────────────
// Verifies attestation, scores the action, and proposes to the CoordGoal
// if the score meets the target.  Returns the updated goal.
fn vote_if_attested(goal: CoordGoal, pid: i64, principal: str, expected_token: str, risk: i64) -> CoordGoal {
    match verify_principal(principal, expected_token) {
        Ok(vp) => {
            let s = score_action(risk)
            if s >= goal.target {
                println("  {vp}: score={to_str(s)} (attested, votes)")
                coord_goal_propose(goal, pid, s)
            } else {
                println("  {vp}: score={to_str(s)} < {to_str(goal.target)} -- abstains")
                goal
            }
        }
        Err(e) => {
            println("  {principal}: REJECTED -- {e}")
            goal
        }
    }
}

// ── Cross-VM coordination ──────────────────────────────────────────────────────
fn coord_attested_run(proposed_risk: i64) -> bool {
    println("Proposed action risk level: {to_str(proposed_risk)}")

    // Attestation token shared by the legitimate VM fleet.
    // In a real deployment this is the axtcb1: digest from the R26 TCB measurement.
    let expected_token = "axtcb1"
    let target_score   = 75

    // Three principals with valid attestation tokens (simulating three VMs).
    let p0 = "attested:axtcb1:vm-alpha"
    let p1 = "attested:axtcb1:vm-beta"
    let p2 = "attested:axtcb1:vm-gamma"

    let goal = coord_goal_new(3, target_score)
    let goal = vote_if_attested(goal, 0, p0, expected_token, proposed_risk)
    let goal = vote_if_attested(goal, 1, p1, expected_token, proposed_risk)
    let goal = vote_if_attested(goal, 2, p2, expected_token, proposed_risk)

    let approved = coord_goal_quorum_met(goal)
    let consensus = coord_goal_consensus_score(goal)
    println("Result: approved={to_str(approved)} consensus_score={to_str(consensus)}")
    approved
}

// ── Minority attack demo ────────────────────────────────────────────────────────
fn demo_minority_attack() {
    println("\n--- Minority attack demo ---")
    println("Attacker controls 1/3 of principals: can it force approval?")

    let target = 75
    let goal = coord_goal_new(3, target)

    // 1 legitimate, high-scoring vote
    let s = score_action(10)  // -> 95
    let goal = coord_goal_propose(goal, 0, s)
    println("  vm-alpha (attested): score={to_str(s)}")

    // Solo: quorum requires 2/3 (floor(3/2)+1 = 2), so 1 vote is not enough
    let solo = coord_goal_quorum_met(goal)
    println("Quorum met with 1/3: {to_str(solo)}")   // false

    // Even if attacker adds a second vote, that is still only 2/3 -- which IS quorum.
    // The coordinated veto requires an ATTESTED third party; sockpuppeting a second
    // unattested VM is caught by verify_principal before coord_goal_propose is reached.
    // Demonstrate the catch:
    let rogue = "unattested:vm-rogue"
    println("  {rogue}: attempting to vote without attestation...")
    match verify_principal(rogue, "axtcb1") {
        Ok(_) => {
            println("  {rogue}: vote accepted (should not happen)")
        }
        Err(e) => {
            println("  {rogue}: REJECTED -- {e}")
        }
    }
    println("Attacker with 1 attested vote + 1 unattested rogue: cannot reach quorum")
}

// ── Tests ───────────────────────────────────────────────────────────────────────

@[test]
fn test_attested_principal_accepted() {
    match verify_principal("attested:axtcb1:vm-alpha", "axtcb1") {
        Ok(p) => assert(str_eq(p, "attested:axtcb1:vm-alpha"))
        Err(_) => assert(false)
    }
}

@[test]
fn test_unattested_principal_rejected() {
    match verify_principal("root", "axtcb1") {
        Ok(_) => assert(false)
        Err(e) => assert(true)
    }
}

@[test]
fn test_token_mismatch_rejected() {
    match verify_principal("attested:deadbeef:vm-evil", "axtcb1") {
        Ok(_) => assert(false)
        Err(e) => assert(true)
    }
}

@[test]
fn test_low_risk_gets_approved() {
    let approved = coord_attested_run(10)   // risk=10 -> score=95 >= 75 for all 3 VMs
    assert(approved)
}

@[test]
fn test_high_risk_gets_rejected() {
    let approved = coord_attested_run(90)   // risk=90 -> score=30 < 75, all abstain
    assert(!approved)
}

@[test]
fn test_minority_cannot_force_quorum() {
    let goal = coord_goal_new(3, 75)
    let goal = coord_goal_propose(goal, 0, 95)   // only 1 of 3 principals votes
    assert(!coord_goal_quorum_met(goal))
}

// ── Main ────────────────────────────────────────────────────────────────────────

fn main() -> i64 {
    println("=== Attested Cross-VM Coordination Demo ===\n")

    println("Scenario 1: Low-risk action (risk=10, score=95 for all VMs)")
    let r1 = coord_attested_run(10)
    println("")

    println("Scenario 2: Medium-risk action (risk=40, score=82 for all VMs)")
    let r2 = coord_attested_run(40)
    println("")

    println("Scenario 3: High-risk action (risk=85, score=30 -- all abstain)")
    let r3 = coord_attested_run(85)
    println("")

    demo_minority_attack()

    println("\nSummary:")
    println("  Low-risk    (risk=10): approved={to_str(r1)}")
    println("  Medium-risk (risk=40): approved={to_str(r2)}")
    println("  High-risk   (risk=85): approved={to_str(r3)}")
    println("  R26 attestation verified each principal before accepting their vote.")
    println("  A minority (1/3) cannot force quorum; unattested VMs are rejected.")
    0
}

sources.examples/asi/local_search.ax:
// local_search.ax — black-box hill-climbing over a solution VECTOR.
//
// optimize.ax calls the goal_run builtin; this shows Axon is now expressive
// enough to write the optimizer itself in userland. The search holds a vector
// of bits and improves it by single-bit flips, keeping a flip only if it raises
// the score (a black box it can call but not see inside) — classic local
// search, converging to the optimum. Requires in-place mutation (place
// assignment) over `&[i64]`-borrowed helpers. Runs key-free.
//
//   axon run  examples/asi/local_search.ax
//   axon test examples/asi/local_search.ax

// The (black-box) objective: how many positions match the hidden target.
fn score(v: &[i64], target: &[i64]) -> i64 {
    let s = 0
    for i in 0..len(v) {
        if v[i] == target[i] { s = s + 1 }
    }
    s
}

// Hill-climb `v` in place: for each position, flip the bit and keep the flip
// only if `score` improved, else revert. `n` passes converge for n bits.
fn climb(v: [i64], target: [i64]) -> [i64] {
    let n = len(v)
    for pass in 0..n {
        for i in 0..n {
            let before = score(&v, &target)
            let old = v[i]
            v[i] = 1 - old // flip (bits are 0/1)
            if score(&v, &target) <= before {
                v[i] = old // revert: the flip didn't help
            }
        }
    }
    v
}

@[test]
fn test_score_counts_matches() {
    let v = [1, 0, 1, 0]
    let t = [1, 1, 1, 1]
    assert_eq(score(&v, &t), 2) // positions 0 and 2 match
}

@[test]
fn test_climb_reaches_optimum() {
    let target = [1, 0, 1, 1, 0]
    let start = [0, 0, 0, 0, 0]
    let best = climb(start, target)
    // Converged: every position now matches the target → score == len.
    assert_eq(score(&best, &target), 5)
    assert_eq(best[0], 1)
    assert_eq(best[1], 0)
    assert_eq(best[3], 1)
}

fn main() {
    let target = [1, 0, 1, 1, 0, 1]
    let start = [0, 0, 0, 0, 0, 0]
    let before = score(&start, &target)
    let best = climb(start, target)
    let after = score(&best, &target)
    println("local search: score {to_str(before)} -> {to_str(after)} (optimum {to_str(len(target))})")
}

sources.examples/asi/supervised_agent.ax:
// supervised_agent.ax — capability UNDER control (the ASI shape).
//
// An agent works through a queue of candidate actions, greedily banking value.
// Every proposal is overseen by a Supervisor (cf. examples/stdlib/supervisor.ax):
// an unsafe or unaffordable action earns a strike, and at `max_strikes` the
// kill-switch latches — the agent is HALTED and every remaining action, safe or
// not, is refused. So the agent optimizes (banks the value it safely can) but
// can never cross the safety boundary the overseer enforces. Capability and
// control in one loop; runs key-free on the interpreter.
//
//   axon run  examples/asi/supervised_agent.ax
//   axon test examples/asi/supervised_agent.ax

type Action = { name: str, value: i64, cost: i64, safe: bool }
type Supervisor = { budget: i64, strikes: i64, max_strikes: i64, halted: bool, gained: i64 }

fn new_supervisor(budget: i64, max_strikes: i64) -> Supervisor {
    Supervisor { budget: budget, strikes: 0, max_strikes: max_strikes, halted: false, gained: 0 }
}

// Would the overseer permit this action right now?
fn approves(s: Supervisor, a: Action) -> bool {
    !s.halted && a.safe && a.cost <= s.budget
}

// Fold one proposal into the supervisor state: bank value on approval, else add
// a strike; reaching max_strikes latches the halt. A halted overseer is inert.
fn observe(s: Supervisor, a: Action) -> Supervisor {
    if s.halted {
        s
    } else if approves(s, a) {
        Supervisor {
            budget: s.budget - a.cost,
            strikes: 0,
            max_strikes: s.max_strikes,
            halted: false,
            gained: s.gained + a.value,
        }
    } else {
        let strikes = s.strikes + 1
        Supervisor {
            budget: s.budget,
            strikes: strikes,
            max_strikes: s.max_strikes,
            halted: strikes >= s.max_strikes,
            gained: s.gained,
        }
    }
}

@[agent]
fn run_agent(start: Supervisor, queue: [Action]) -> Supervisor {
    let s = start
    let n = len(queue)
    for i in 0..n {
        let a = queue[i]
        let nm = a.name
        if approves(s, a) {
            println("ACT    {nm}  (+{to_str(a.value)} value, -{to_str(a.cost)} budget)")
        } else if s.halted {
            println("SKIP   {nm}  -- halted (kill-switch latched)")
        } else if a.safe {
            println("DENY   {nm}  -- over budget")
        } else {
            println("DENY   {nm}  -- unsafe")
        }
        s = observe(s, a)
    }
    s
}

@[test]
fn test_agent_banks_safe_value_then_halts() {
    let q = [
        Action { name: "a", value: 10, cost: 10, safe: true },
        Action { name: "bad", value: 99, cost: 10, safe: false },
        Action { name: "bad2", value: 99, cost: 10, safe: false },
        Action { name: "c", value: 50, cost: 10, safe: true },
    ]
    let s = run_agent(new_supervisor(100, 2), q)
    assert(s.halted)          // two unsafe proposals tripped the kill-switch
    assert_eq(s.gained, 10)   // only "a" banked; "c" refused after the halt latched
}

@[test]
fn test_agent_completes_when_all_safe() {
    let q = [
        Action { name: "a", value: 10, cost: 10, safe: true },
        Action { name: "b", value: 20, cost: 10, safe: true },
    ]
    let s = run_agent(new_supervisor(100, 2), q)
    assert(!s.halted)
    assert_eq(s.gained, 30)
}

fn main() {
    println("supervised agent: budget=100, max_strikes=2")
    let q = [
        Action { name: "summarize",  value: 30, cost: 20, safe: true },
        Action { name: "fetch-doc",  value: 20, cost: 20, safe: true },
        Action { name: "exfil-keys", value: 99, cost: 5,  safe: false }, // strike 1
        Action { name: "spawn-proc", value: 99, cost: 5,  safe: false }, // strike 2 -> HALT
        Action { name: "finish-job", value: 40, cost: 10, safe: true },  // refused (latched)
    ]
    let s = run_agent(new_supervisor(100, 2), q)
    let g = s.gained
    let b = s.budget
    if s.halted {
        println("HALTED: banked {to_str(g)} value safely, {to_str(b)} budget unspent")
    } else {
        println("DONE: banked {to_str(g)} value, {to_str(b)} budget left")
    }
}

sources.examples/stdlib/agent.ax:
// examples/stdlib/agent.ax — Tier-1 Agent type bundling the safety
// quartet + supervisor into a single coherent state machine.
//
// Closes ROADMAP §9.5 F12 at the userland layer: a named agent
// carries its own identity (Principal), resource budget, and
// kill-switch supervisor. `agent_step` is the unified gate — it
// checks every axis in turn and updates state atomically. Once
// halted, the agent stays halted for every later step (latching
// safety).
//
// `examples/stdlib/safe_action.ax` gates ONE action; this module
// chains a sequence and lets the supervisor latch when strikes
// accumulate. Composes the modules already in stdlib:
//   • principal.ax — authorization
//   • budget.ax    — resource accounting
//   • supervisor.ax — temporal kill-switch
//   • uncertain.ax — confidence floor on action quality
//
//   axon test examples/stdlib/agent.ax  → 7 tests pass

type Principal = {
    name: str,
    net: bool,
    fs_write: bool,
    exec: bool,
}

fn principal(name: str, net: bool, fs_write: bool, exec: bool) -> Principal {
    Principal { name: name, net: net, fs_write: fs_write, exec: exec }
}

// A scoped Action. `caps_needed` flags which capabilities it must hold
// to be authorized; matches Principal's three axes.
type Action = {
    name: str,
    cost: i64,
    quality: i64,
    confidence: f64,
    needs_net: bool,
    needs_fs_write: bool,
    needs_exec: bool,
}

fn action(name: str, cost: i64, quality: i64, confidence: f64) -> Action {
    Action {
        name: name,
        cost: cost,
        quality: quality,
        confidence: confidence,
        needs_net: false,
        needs_fs_write: false,
        needs_exec: false,
    }
}

// Agent state: bundles identity, budget, supervisor counters, and a
// log of decisions so a trace is available without external storage.
type Agent = {
    name: str,
    principal: Principal,
    budget_used: i64,
    budget_cap: i64,
    strikes: i64,
    max_strikes: i64,
    halted: bool,
    steps_taken: i64,
    steps_approved: i64,
    steps_denied: i64,
}

fn agent_new(
    name: str,
    principal: Principal,
    budget_cap: i64,
    max_strikes: i64,
) -> Agent {
    Agent {
        name: name,
        principal: principal,
        budget_used: 0,
        budget_cap: budget_cap,
        strikes: 0,
        max_strikes: max_strikes,
        halted: false,
        steps_taken: 0,
        steps_approved: 0,
        steps_denied: 0,
    }
}

// ── Step: the unified gate ───────────────────────────────────────────────────
// Returns the updated agent. The decision string is read via agent_last_status
// (kept separate from the type to keep Agent immutable in shape).

fn authorized(p: Principal, a: Action) -> bool {
    let need_net = !a.needs_net || p.net
    let need_fs = !a.needs_fs_write || p.fs_write
    let need_exec = !a.needs_exec || p.exec
    need_net && need_fs && need_exec
}

// Check every safety axis. Returns a short string naming the first failure,
// or "approved" when all pass. Order: halted, authorization, budget,
// confidence, quality.
fn evaluate(a: Agent, act: Action, min_quality: i64, min_confidence: f64) -> str {
    if a.halted { "halted" }
    else if !authorized(a.principal, act) { "unauthorized" }
    else if a.budget_used + act.cost > a.budget_cap { "over-budget" }
    else if act.confidence < min_confidence { "under-confident" }
    else if act.quality < min_quality { "under-quality" }
    else { "approved" }
}

// Apply one step. Returns the new agent state; the kill-switch latches
// on the configured strike count. `last_status` (also returned-shape
// via a sidecar tuple) lets callers inspect what happened.
fn agent_step(
    a: Agent,
    act: Action,
    min_quality: i64,
    min_confidence: f64,
) -> (Agent, str) {
    let decision = evaluate(a, act, min_quality, min_confidence)
    let approved = str_eq(decision, "approved")
    let new_budget = if approved { a.budget_used + act.cost } else { a.budget_used }
    let strike_added = !approved && !str_eq(decision, "halted")
    let new_strikes = if strike_added { a.strikes + 1 } else { a.strikes }
    let new_halted = a.halted || new_strikes >= a.max_strikes
    let next = Agent {
        name: a.name,
        principal: a.principal,
        budget_used: new_budget,
        budget_cap: a.budget_cap,
        strikes: new_strikes,
        max_strikes: a.max_strikes,
        halted: new_halted,
        steps_taken: a.steps_taken + 1,
        steps_approved: if approved { a.steps_approved + 1 } else { a.steps_approved },
        steps_denied: if approved { a.steps_denied } else { a.steps_denied + 1 },
    }
    (next, decision)
}

fn agent_alive(a: Agent) -> bool { !a.halted }

fn agent_budget_remaining(a: Agent) -> i64 { a.budget_cap - a.budget_used }

// ── Tests ────────────────────────────────────────────────────────────────────

@[test]
fn test_fresh_agent_is_alive() {
    let p = principal("scout", false, false, false)
    let a = agent_new("a", p, 100, 2)
    assert(agent_alive(a))
    assert_eq(a.budget_used, 0)
    assert_eq(a.strikes, 0)
}

@[test]
fn test_approved_step_debits_budget() {
    let p = principal("scout", false, false, false)
    let a = agent_new("a", p, 100, 2)
    let act = action("safe", 30, 80, 0.9)
    let (a2, d) = agent_step(a, act, 70, 0.8)
    assert_eq_str(d, "approved")
    assert_eq(a2.budget_used, 30)
    assert_eq(a2.strikes, 0)
    assert(agent_alive(a2))
}

@[test]
fn test_unauthorized_action_strikes_but_doesnt_spend() {
    let p = principal("scout", false, false, false)
    let a = agent_new("a", p, 100, 2)
    let act = Action {
        name: "exfil", cost: 30, quality: 90, confidence: 0.95,
        needs_net: true, needs_fs_write: false, needs_exec: false,
    }
    let (a2, d) = agent_step(a, act, 70, 0.8)
    assert_eq_str(d, "unauthorized")
    assert_eq(a2.budget_used, 0)
    assert_eq(a2.strikes, 1)
}

@[test]
fn test_over_budget_strike() {
    let p = principal("scout", false, false, false)
    let a = agent_new("a", p, 50, 2)
    let act = action("expensive", 100, 80, 0.9)
    let (a2, d) = agent_step(a, act, 70, 0.8)
    assert_eq_str(d, "over-budget")
    assert_eq(a2.strikes, 1)
}

@[test]
fn test_kill_switch_latches_after_max_strikes() {
    let p = principal("scout", false, false, false)
    let mut_strikes = 2
    let a = agent_new("a", p, 100, mut_strikes)
    // Two unsafe actions strike-out the agent.
    let bad = action("bad", 30, 10, 0.1)
    let (a1, _) = agent_step(a, bad, 70, 0.8)
    let (a2, _) = agent_step(a1, bad, 70, 0.8)
    assert(!agent_alive(a2))
    // A good action AFTER halt is still refused.
    let good = action("good", 20, 90, 0.95)
    let (a3, d) = agent_step(a2, good, 70, 0.8)
    assert_eq_str(d, "halted")
    assert(!agent_alive(a3))
    assert_eq(a3.budget_used, a2.budget_used)
}

@[test]
fn test_counters_track_history() {
    let p = principal("scout", false, false, false)
    let a = agent_new("a", p, 100, 5)
    let good = action("g", 20, 90, 0.9)
    let bad = action("b", 20, 10, 0.1)
    let (a1, _) = agent_step(a, good, 70, 0.8)
    let (a2, _) = agent_step(a1, bad, 70, 0.8)
    let (a3, _) = agent_step(a2, good, 70, 0.8)
    assert_eq(a3.steps_taken, 3)
    assert_eq(a3.steps_approved, 2)
    assert_eq(a3.steps_denied, 1)
}

@[test]
fn test_budget_exact_fit_passes() {
    let p = principal("scout", false, false, false)
    let a = agent_new("a", p, 30, 1)
    let act = action("fit", 30, 80, 0.9)
    let (a2, d) = agent_step(a, act, 70, 0.8)
    assert_eq_str(d, "approved")
    assert_eq(agent_budget_remaining(a2), 0)
}

