// examples/stdlib/bandit.ax — UCB1 multi-armed bandit as a reusable
// userland module. Importable via `mod bandit` from any program.
//
// The bandit's state is two Dict<str, …> handles wrapped in a struct.
// The Dicts are reference-shared (Rc<RefCell<…>>) so `bandit_update`
// mutates them in place — passing the Bandit by value to a helper
// still updates the same underlying running averages.
//
//   axon test examples/stdlib/bandit.ax  → 5 tests pass

type Bandit = {
    n_arms: i64,
    sums: Dict,        // total reward per arm
    counts: Dict,      // pull count per arm
}

fn arm_key(id: i64) -> str {
    // Stable string key per arm so two Bandits with the same arm count
    // share a key space (useful for cross-run persistence later).
    if id == 0 { "arm-0" }
    else if id == 1 { "arm-1" }
    else if id == 2 { "arm-2" }
    else if id == 3 { "arm-3" }
    else if id == 4 { "arm-4" }
    else if id == 5 { "arm-5" }
    else if id == 6 { "arm-6" }
    else if id == 7 { "arm-7" }
    else { "arm-x" }     // beyond v1's 8-arm cap
}

fn bandit_new(n_arms: i64) -> Bandit {
    Bandit {
        n_arms: n_arms,
        sums: dict_new(),
        counts: dict_new(),
    }
}

// UCB score for one arm given total pull count `t`.
fn bandit_ucb(b: Bandit, id: i64, t: i64) -> f64 {
    let k = arm_key(id)
    let n = dict_get_or(b.counts, k, 0)
    if n == 0 {
        1.0e9                    // unpulled → infinite UCB, sweep arms first
    } else {
        let sum_r = dict_get_or(b.sums, k, 0.0)
        let mean = sum_r / as_f64(n)
        let bonus = sqrt(2.0 * ln(as_f64(t)) / as_f64(n))
        mean + bonus
    }
}

// Pick the arm maximizing UCB. Total pull count `t` should be the
// number of bandit_update calls so far + 1 (the round we're about
// to run).
fn bandit_select(b: Bandit, t: i64) -> i64 {
    let ids = arr_range(0, b.n_arms)
    let scored = arr_map(ids, |i| (i, bandit_ucb(b, i, t)))
    let best = arr_max_by(scored, |p| p.1)
    best.0
}

// Observe a reward for an arm; mutates the Dicts in place.
fn bandit_update(b: Bandit, arm: i64, reward: f64) {
    let k = arm_key(arm)
    let cur_sum = dict_get_or(b.sums, k, 0.0)
    dict_set(b.sums, k, cur_sum + reward)
    let _ = dict_inc(b.counts, k)
}

// Read-only queries.
fn bandit_pulls(b: Bandit, arm: i64) -> i64 {
    dict_get_or(b.counts, arm_key(arm), 0)
}

fn bandit_mean(b: Bandit, arm: i64) -> f64 {
    let n = bandit_pulls(b, arm)
    if n == 0 { 0.0 }
    else {
        let s = dict_get_or(b.sums, arm_key(arm), 0.0)
        s / as_f64(n)
    }
}

// Most-pulled arm — UCB's revealed preference at convergence.
fn bandit_best_arm(b: Bandit) -> i64 {
    let ids = arr_range(0, b.n_arms)
    let pulls = arr_map(ids, |i| (i, bandit_pulls(b, i)))
    let best = arr_max_by(pulls, |p| as_f64(p.1))
    best.0
}

// ── Tests ────────────────────────────────────────────────────────────────────

@[test]
fn test_fresh_bandit_has_zero_pulls() {
    let b = bandit_new(3)
    assert_eq(bandit_pulls(b, 0), 0)
    assert_eq(bandit_pulls(b, 1), 0)
    assert_eq(bandit_pulls(b, 2), 0)
}

@[test]
fn test_update_increments_count_and_sum() {
    let b = bandit_new(3)
    bandit_update(b, 1, 0.5)
    bandit_update(b, 1, 0.7)
    assert_eq(bandit_pulls(b, 1), 2)
    // mean = (0.5 + 0.7) / 2 = 0.6
    let m = bandit_mean(b, 1)
    assert(m > 0.59 && m < 0.61)
}

@[test]
fn test_select_sweeps_unpulled_arms_first() {
    // First three selects should each return a different arm,
    // since unpulled arms get an "infinite" UCB.
    let b = bandit_new(3)
    let a = bandit_select(b, 1)
    bandit_update(b, a, 0.1)
    let c = bandit_select(b, 2)
    bandit_update(b, c, 0.2)
    let e = bandit_select(b, 3)
    bandit_update(b, e, 0.3)
    // All three pulls happened on distinct arms.
    let picked = [a, c, e]
    assert_eq(len(arr_unique(picked)), 3)
}

@[test]
fn test_best_arm_is_the_most_pulled() {
    let b = bandit_new(3)
    bandit_update(b, 0, 0.1)
    bandit_update(b, 1, 0.5)
    bandit_update(b, 1, 0.5)
    bandit_update(b, 1, 0.5)
    bandit_update(b, 2, 0.1)
    bandit_update(b, 2, 0.1)
    assert_eq(bandit_best_arm(b), 1)
}

@[test]
fn test_state_shared_via_rc_refcell() {
    // The Dicts inside Bandit are Rc<RefCell<…>> so a helper that
    // takes a `Bandit` by value still mutates the same state.
    let b = bandit_new(2)
    bandit_update(b, 0, 1.0)
    // Read after update via the same handle.
    assert_eq(bandit_pulls(b, 0), 1)
    let m = bandit_mean(b, 0)
    assert(m > 0.99 && m < 1.01)
}

sources.examples/stdlib/belief.ax:
// Tier-1 stdlib: Belief — discrete Bayesian probabilistic state.
//
// A Belief is a probability distribution over a finite set of named hypotheses.
// Supports Bayesian update (`belief_observe`) and MAP/entropy extraction.
//
// Phase 13: Slice 1 — userland probabilistic state type.
// Uses `categorical_*` distribution builtins + standard Axon array builtins.
//
//   axon test examples/stdlib/belief.ax   # run @[test]s
//   axon run  examples/stdlib/belief.ax   # demo

// ── Belief type ───────────────────────────────────────────────────────────────

type Belief = { labels: [str], probs: [f64] }

// ── Helpers ───────────────────────────────────────────────────────────────────

fn approx_eq_b(a: f64, b: f64, tol: f64) -> bool {
    let d = a - b
    d >= -tol && d <= tol
}

// ── Constructors ──────────────────────────────────────────────────────────────

// Uniform belief over `labels`.
fn belief_uniform(labels: [str]) -> Belief {
    let n = len(labels)
    assert(n > 0)
    let p = 1.0 / (n as f64)
    let probs = arr_repeat(p, n)
    Belief { labels: labels, probs: probs }
}

// Belief from explicit labels + probability masses.
fn belief_new(labels: [str], probs: [f64]) -> Belief {
    assert(len(labels) == len(probs))
    Belief { labels: labels, probs: probs }
}

// ── Queries ───────────────────────────────────────────────────────────────────

// Number of hypotheses.
fn belief_size(b: Belief) -> i64 {
    len(b.labels)
}

// Probability of the hypothesis labelled `name` (0.0 if absent).
fn belief_prob(b: Belief, name: str) -> f64 {
    let n = len(b.labels)
    let i = 0
    let found = 0.0
    while i < n {
        if str_eq(b.labels[i], name) {
            found = b.probs[i]
        }
        i = i + 1
    }
    found
}

// Index of the most probable hypothesis.
fn belief_map_index(b: Belief) -> i64 {
    arr_argmax_f64(b.probs)
}

// Label of the most probable hypothesis.
fn belief_map(b: Belief) -> str {
    let idx = belief_map_index(b)
    b.labels[idx]
}

// Entropy -sum(p*ln(p)) in nats (0 for a degenerate distribution).
fn belief_entropy(b: Belief) -> f64 {
    let n = len(b.probs)
    let h = 0.0
    let i = 0
    while i < n {
        let p = b.probs[i]
        if p > 0.0 {
            h = h - p * ln(p)
        }
        i = i + 1
    }
    h
}

// Sample a hypothesis index (impure: Random effect).
fn belief_sample_index(b: Belief) -> i64 {
    categorical_sample(b.probs)
}

// Sample a hypothesis label (impure: Random effect).
fn belief_sample(b: Belief) -> str {
    b.labels[belief_sample_index(b)]
}

// ── Bayesian update ───────────────────────────────────────────────────────────

// Multiply prior probs element-wise by likelihoods and renormalize.
// Returns the posterior Belief.
fn belief_observe(b: Belief, likelihoods: [f64]) -> Belief {
    let n = len(b.probs)
    assert(len(likelihoods) == n)
    // Compute unnormalized weights: zip probs with likelihoods, then multiply
    let pairs = arr_zip(b.probs, likelihoods)
    let unnorm = arr_map(pairs, |pair| pair.0 * pair.1)
    let total = arr_sum_f64(unnorm)
    assert(total > 0.0)
    let normalized = arr_map(unnorm, |p| p / total)
    Belief { labels: b.labels, probs: normalized }
}

// ── Tests ─────────────────────────────────────────────────────────────────────

@[test]
fn test_belief_uniform_sums_to_one() {
    let b = belief_uniform(["a", "b", "c", "d"])
    let total = arr_sum_f64(b.probs)
    assert(approx_eq_b(total, 1.0, 0.001))
}

@[test]
fn test_belief_uniform_equal_probs() {
    let b = belief_uniform(["x", "y"])
    assert(approx_eq_b(b.probs[0], 0.5, 0.001))
    assert(approx_eq_b(b.probs[1], 0.5, 0.001))
}

@[test]
fn test_belief_prob_lookup() {
    let b = belief_new(["cat", "dog", "fish"], [0.5, 0.3, 0.2])
    assert(approx_eq_b(belief_prob(b, "cat"), 0.5, 0.001))
    assert(approx_eq_b(belief_prob(b, "dog"), 0.3, 0.001))
    assert(approx_eq_b(belief_prob(b, "fish"), 0.2, 0.001))
    assert(approx_eq_b(belief_prob(b, "bird"), 0.0, 0.001))
}

@[test]
fn test_belief_map() {
    let b = belief_new(["A", "B", "C"], [0.1, 0.7, 0.2])
    assert(str_eq(belief_map(b), "B"))
}

@[test]
fn test_belief_map_index() {
    let b = belief_new(["p", "q", "r"], [0.3, 0.2, 0.5])
    assert_eq(belief_map_index(b), 2)
}

@[test]
fn test_belief_entropy_uniform_exceeds_degenerate() {
    let b_uniform = belief_new(["a", "b", "c", "d"], [0.25, 0.25, 0.25, 0.25])
    let b_degenerate = belief_new(["a", "b"], [1.0, 0.0])
    assert(belief_entropy(b_uniform) > belief_entropy(b_degenerate))
}

@[test]
fn test_belief_entropy_degenerate_is_zero() {
    let b = belief_new(["only"], [1.0])
    assert(approx_eq_b(belief_entropy(b), 0.0, 0.001))
}

@[test]
fn test_belief_observe_basic() {
    // Prior 50/50, evidence: H0 is 4x more likely than H1
    let prior = belief_new(["H0", "H1"], [0.5, 0.5])
    let posterior = belief_observe(prior, [0.8, 0.2])
    assert(approx_eq_b(posterior.probs[0], 0.8, 0.001))
    assert(approx_eq_b(posterior.probs[1], 0.2, 0.001))
}

@[test]
fn test_belief_observe_updates_map() {
    let prior = belief_new(["A", "B", "C"], [0.33, 0.33, 0.34])
    let posterior = belief_observe(prior, [0.1, 0.8, 0.1])
    assert(str_eq(belief_map(posterior), "B"))
}

@[test]
fn test_belief_size() {
    let b = belief_new(["a", "b", "c"], [0.2, 0.3, 0.5])
    assert_eq(belief_size(b), 3)
}

fn main() {
    let prior = belief_new(["cloudy", "sunny", "rainy"], [0.3, 0.4, 0.3])
    println("Prior MAP: {belief_map(prior)}")
    println("Entropy: {to_str_f64(belief_entropy(prior))}")
    let posterior = belief_observe(prior, [0.7, 0.1, 0.9])
    println("Posterior MAP: {belief_map(posterior)}")
    println("P(rainy|obs): {to_str_f64(posterior.probs[2])}")
}

sources.examples/stdlib/budget.ax:
// Tier-1 stdlib: Budget — bounded resource tracking for ASI goal loops.
//
// A Budget caps a consumable resource (LLM calls, tokens, evaluations). Values
// are immutable: `budget_spend` returns a new Budget. Goals use it to enforce
// the "budget overrun aborts the run" contract from a goal's Budget section.
//
//   axon test examples/stdlib/budget.ax     # run the @[test]s
//   axon run  examples/stdlib/budget.ax     # demo

type Budget = { used: i64, cap: i64 }

fn budget_new(cap: i64) -> Budget {
    Budget { used: 0, cap: cap }
}

// Record `amount` of spend, returning the updated budget.
fn budget_spend(b: Budget, amount: i64) -> Budget {
    Budget { used: b.used + amount, cap: b.cap }
}

// Remaining headroom, clamped at 0.
fn budget_remaining(b: Budget) -> i64 {
    let r = b.cap - b.used
    if r < 0 { 0 } else { r }
}

fn budget_exhausted(b: Budget) -> bool {
    b.used >= b.cap
}

// Whether `amount` more spend would stay within cap.
fn budget_ok(b: Budget, amount: i64) -> bool {
    b.used + amount <= b.cap
}

// Used fraction as 0..100.
fn budget_used_pct(b: Budget) -> i64 {
    if b.cap <= 0 { 100 } else { clamp_i64(b.used * 100 / b.cap, 0, 100) }
}

@[test]
fn test_budget_new() {
    let b = budget_new(100)
    assert_eq(b.cap, 100)
    assert_eq(b.used, 0)
}

@[test]
fn test_budget_spend_and_remaining() {
    let b = budget_spend(budget_new(100), 30)
    assert_eq(b.used, 30)
    assert_eq(budget_remaining(b), 70)
}

@[test]
fn test_budget_exhausted() {
    let b = budget_spend(budget_new(10), 10)
    assert(budget_exhausted(b))
    let c = budget_spend(budget_new(10), 4)
    assert(!budget_exhausted(c))
}

@[test]
fn test_budget_ok() {
    let b = budget_spend(budget_new(10), 8)
    assert(budget_ok(b, 2))
    assert(!budget_ok(b, 3))
}

@[test]
fn test_budget_used_pct() {
    let b = budget_spend(budget_new(200), 150)
    assert_eq(budget_used_pct(b), 75)
}

// ── Budget<R...> — extensible cost over a RESOURCE SET ──────────────────────
//
// The single-resource `Budget` above caps one consumable. The Tier-1 type
// `Budget<R...>` (ROADMAP §6 row 7) is "extensible cost over resource set R": an
// ASI run is bounded on SEVERAL axes at once — model CALLS, TOKENS, and µ$ COST
// — and the run must abort the moment ANY axis is exhausted, not just the total.
// Axon has no generics-over-resource-sets yet, so this models the canonical ASI
// resource quartet concretely. Each axis has its own cap; one overrun on any
// axis exhausts the WHOLE budget (the conjunctive contract — you can't trade a
// token surplus for a call deficit). Immutable: `rb_spend` returns a new value.

type ResBudget = {
    calls_used: i64,   calls_cap: i64,    // model invocations
    tokens_used: i64,  tokens_cap: i64,   // tokens consumed
    cost_used: i64,    cost_cap: i64,     // spend in µ$
}

fn rb_new(calls_cap: i64, tokens_cap: i64, cost_cap: i64) -> ResBudget {
    ResBudget {
        calls_used: 0,  calls_cap: calls_cap,
        tokens_used: 0, tokens_cap: tokens_cap,
        cost_used: 0,   cost_cap: cost_cap,
    }
}

// Charge one call that consumed `tokens` tokens at `rate_micro` µ$/1000 tokens.
// Returns the updated budget (immutable). Spend is recorded even past a cap —
// `rb_exhausted` then reports the breach; `rb_ok` is the pre-check that prevents
// it (the "look before you leap" call site).
fn rb_spend(b: ResBudget, tokens: i64, cost_micro: i64) -> ResBudget {
    ResBudget {
        calls_used: b.calls_used + 1,        calls_cap: b.calls_cap,
        tokens_used: b.tokens_used + tokens, tokens_cap: b.tokens_cap,
        cost_used: b.cost_used + cost_micro, cost_cap: b.cost_cap,
    }
}

// Exhausted iff ANY axis is at/over its cap (the conjunctive contract).
// (Operators kept trailing so the multi-line expr parses — a leading `||`/`&&`
// on a continuation line breaks the lexer, see the continuation gotcha.)
fn rb_exhausted(b: ResBudget) -> bool {
    let calls = b.calls_used >= b.calls_cap
    let tokens = b.tokens_used >= b.tokens_cap
    let cost = b.cost_used >= b.cost_cap
    calls || tokens || cost
}

// Would charging one more call of `tokens`/`cost_micro` stay within EVERY cap?
fn rb_ok(b: ResBudget, tokens: i64, cost_micro: i64) -> bool {
    let calls = b.calls_used + 1 <= b.calls_cap
    let toks = b.tokens_used + tokens <= b.tokens_cap
    let cost = b.cost_used + cost_micro <= b.cost_cap
    calls && toks && cost
}

// The TIGHTEST axis as a used-percent 0..100 — the one closest to exhausting the
// run, i.e. the binding constraint a scheduler should report.
fn rb_tightest_pct(b: ResBudget) -> i64 {
    let cp = if b.calls_cap <= 0 { 100 } else { clamp_i64(b.calls_used * 100 / b.calls_cap, 0, 100) }
    let tp = if b.tokens_cap <= 0 { 100 } else { clamp_i64(b.tokens_used * 100 / b.tokens_cap, 0, 100) }
    let xp = if b.cost_cap <= 0 { 100 } else { clamp_i64(b.cost_used * 100 / b.cost_cap, 0, 100) }
    max_i64(cp, max_i64(tp, xp))
}

@[test]
fn test_rb_new_is_empty() {
    let b = rb_new(10, 5000, 100000)
    assert_eq(b.calls_used, 0)
    assert_eq(b.tokens_used, 0)
    assert_eq(b.cost_used, 0)
    assert(!rb_exhausted(b))
}

@[test]
fn test_rb_spend_accumulates_all_axes() {
    let b = rb_spend(rb_new(10, 5000, 100000), 800, 1200)
    assert_eq(b.calls_used, 1)
    assert_eq(b.tokens_used, 800)
    assert_eq(b.cost_used, 1200)
}

@[test]
fn test_rb_any_axis_overrun_exhausts() {
    // Tokens cap is the binding axis: 3 calls of 400 tokens = 1200 > 1000, even
    // though calls (3 < 10) and cost (well under) have headroom.
    let b0 = rb_new(10, 1000, 1000000)
    let b1 = rb_spend(b0, 400, 10)
    let b2 = rb_spend(b1, 400, 10)
    let b3 = rb_spend(b2, 400, 10)
    assert(rb_exhausted(b3))          // token axis breached
    assert(!rb_exhausted(b2))         // 800 < 1000, still ok
    assert(b3.calls_used < b3.calls_cap)  // calls had headroom — proves it's the TOKEN axis
}

@[test]
fn test_rb_ok_is_conjunctive() {
    // One call from the call cap, with cost headroom but NO token headroom.
    let b = rb_spend(rb_new(2, 500, 100000), 450, 100)
    assert(rb_ok(b, 40, 100))   // 450+40=490 ≤ 500, call 2 ≤ 2, cost ok → all pass
    assert(!rb_ok(b, 60, 100))  // 450+60=510 > 500 → token axis fails → whole check fails
}

@[test]
fn test_rb_tightest_pct_is_the_binding_axis() {
    // calls 50%, tokens 90%, cost 10% → tightest is tokens at 90.
    let b = ResBudget {
        calls_used: 5,  calls_cap: 10,
        tokens_used: 900, tokens_cap: 1000,
        cost_used: 100, cost_cap: 1000,
    }
    assert_eq(rb_tightest_pct(b), 90)
}

fn main() {
    // Single-resource: simulate an LLM run against an 8000-token budget.
    let b = budget_spend(budget_spend(budget_new(8000), 1200), 900)
    println("budget: used {to_str(b.used)} / {to_str(b.cap)} tokens, {to_str(budget_used_pct(b))}% used, {to_str(budget_remaining(b))} remaining")
    if budget_ok(b, 6000) {
        println("next call (6000 tokens): allowed")
    } else {
        println("next call (6000 tokens): BLOCKED — would exceed budget")
    }

    // Multi-resource: an agent loop bounded on 5 calls / 4000 tokens / 50000 µ$.
    // It stops the moment ANY axis would be exceeded — here the token axis binds.
    let rb0 = rb_new(5, 4000, 50000)
    let rb1 = rb_spend(rb0, 1500, 9000)
    let rb = rb_spend(rb1, 1500, 9000)
    println("multi: {to_str(rb.calls_used)}/{to_str(rb.calls_cap)} calls, {to_str(rb.tokens_used)}/{to_str(rb.tokens_cap)} tokens, tightest axis {to_str(rb_tightest_pct(rb))}%")
    if rb_ok(rb, 1500, 9000) {
        println("3rd call (1500 tok): allowed")
    } else {
        println("3rd call (1500 tok): BLOCKED — would exceed the token cap (3000+1500 > 4000)")
    }
}

sources.examples/stdlib/causal.ax:
// Tier-1 stdlib: causal — do-calculus over a small structural causal model.
//
// PRD §"std.causal — Causal Reasoning": `#[goal]` optimization without
// causality finds CORRELATIONS, not LEVERS. It can't tell "ad spend causes
// revenue" from "both are driven by seasonality." This module gives the
// distinction observable, testable semantics in userland (the PRD's full
// `causal.model{nodes, edges, confounders}` literal syntax needs language sugar
// that doesn't exist yet; this is the SEMANTIC CORE, which is the part that
// matters).
//
// The headline (`test_do_and_observe_disagree_under_confounding`): for the SAME
// model, the OBSERVATIONAL association of revenue with ad_spend is INFLATED by a
// seasonality confounder, while the INTERVENTIONAL effect (do-calculus: force
// ad_spend, break the confounder's influence on it) is the true causal lever.
// They DISAGREE — that gap is the whole reason do-calculus exists.
//
// The model (integer arithmetic, all values scaled ×1):
//
//        seasonality ─┐ (confounder: also lifts revenue directly)
//                     ↓
//   ad_spend ──────> revenue
//     (causal: each unit of spend adds `spend_effect` to revenue)
//
//   revenue = base
//           + spend_effect * ad_spend          (the CAUSAL path — the lever)
//           + season_on_revenue * seasonality  (confounder → revenue directly)
//   ad_spend is itself lifted by seasonality   (confounder → ad_spend):
//           ad_spend = season_on_spend * seasonality   (in the observed data)
//
// OBSERVE: in the observed data, high ad_spend co-occurs with high seasonality
// (because seasonality drove both), so revenue-given-high-spend is inflated.
// DO: we SET ad_spend ourselves (an A/B test / forced budget), severing
// seasonality→ad_spend, so only the true `spend_effect` path remains.
//
//   axon test examples/stdlib/causal.ax
//   axon run  examples/stdlib/causal.ax

// A structural causal model for the ad_spend → revenue example. Coefficients
// are the structural equations; `season` is the confounder's current level.
type Causal = {
    base: i64,                // baseline revenue with zero spend, zero season
    spend_effect: i64,        // revenue added per unit of ad_spend (the LEVER)
    season_on_revenue: i64,   // revenue added per unit of seasonality (direct)
    season_on_spend: i64,     // ad_spend induced per unit of seasonality (the
                              // confounding back-door; only present in OBSERVED data)
    season: i64,              // current seasonality level
}

fn causal_new(base: i64, spend_effect: i64, season_on_revenue: i64,
              season_on_spend: i64, season: i64) -> Causal {
    Causal {
        base: base,
        spend_effect: spend_effect,
        season_on_revenue: season_on_revenue,
        season_on_spend: season_on_spend,
        season: season,
    }
}

// The structural equation for revenue given an ad_spend level and the model's
// current seasonality. This is the ground truth the world runs on.
fn revenue_of(m: Causal, ad_spend: i64) -> i64 {
    m.base + m.spend_effect * ad_spend + m.season_on_revenue * m.season
}

// ── OBSERVE: the observational association ───────────────────────────────────
// In the OBSERVED data, ad_spend was not set by us — it was driven by
// seasonality (the back-door). So `observe(revenue | ad_spend = s)` reflects the
// world where that level of spend CO-OCCURRED with the seasonality that produced
// it. The naive analyst reads this slope as "the effect of ad_spend" — and is
// WRONG, because part of the lift is seasonality leaking through the back door.
//
// We report the observed revenue at the spend level that seasonality `season`
// would naturally have produced.
fn observe_revenue(m: Causal) -> i64 {
    let observed_spend = m.season_on_spend * m.season
    revenue_of(m, observed_spend)
}

// ── DO: the interventional (causal) effect ───────────────────────────────────
// `do(ad_spend := s)` SETS the spend ourselves (an experiment), which SEVERS the
// seasonality→ad_spend edge. The only path left from our intervention to revenue
// is the true causal lever `spend_effect`. The seasonality→revenue direct path
// still contributes its baseline, but it no longer RIDES ALONG with spend.
//
// We return the revenue when we FORCE `ad_spend = s`, holding seasonality at its
// level but breaking its influence on spend.
fn do_revenue(m: Causal, forced_spend: i64) -> i64 {
    // Under do(), forced_spend is exogenous; revenue uses the structural eq with
    // the forced value (the confounder no longer determines spend).
    revenue_of(m, forced_spend)
}

// The CAUSAL EFFECT of one extra unit of ad_spend, isolated via do-calculus:
// do(spend = s+1) - do(spend = s). This is the pure lever — what a `#[goal]`
// SHOULD optimize, free of the confounder.
fn causal_effect_per_unit(m: Causal) -> i64 {
    do_revenue(m, 1) - do_revenue(m, 0)
}

// The NAIVE observational "effect" per unit of spend — the slope a correlational
// analysis would report, contaminated by the back-door. Computed as the observed
// revenue change per unit of the seasonality-induced spend.
fn observational_effect_per_unit(m: Causal) -> i64 {
    // At season s, observed spend = season_on_spend * s, observed revenue =
    // observe_revenue. The naive slope attributes ALL of revenue's lift over
    // baseline to that spend.
    let observed_spend = m.season_on_spend * m.season
    if observed_spend == 0 {
        m.spend_effect
    } else {
        let lift = observe_revenue(m) - m.base
        lift / observed_spend
    }
}

// ── COUNTERFACTUAL: "what would revenue have been had we spent X instead?" ────
// Given an observed (revenue, ad_spend) and a hypothetical spend, return the
// revenue under the hypothetical, holding the (inferred) seasonality fixed. This
// is the PRD's "had we spent 50K, revenue would have been 820K" query.
fn counterfactual_revenue(m: Causal, hypothetical_spend: i64) -> i64 {
    // Seasonality is held at the model's level (the observed context); only the
    // causal spend path changes.
    revenue_of(m, hypothetical_spend)
}

// ════════════════════════════════════════════════════════════════════════════
//  Tests — the do-vs-observe distinction is the contract.
// ════════════════════════════════════════════════════════════════════════════

// The HEADLINE: under confounding, the observational effect OVERSTATES the true
// causal effect. A correlational #[goal] would chase the inflated number.
@[test]
fn test_do_and_observe_disagree_under_confounding() {
    // base 100; each unit of spend truly adds 2 to revenue (the lever);
    // seasonality adds 5/unit to revenue directly AND induces 3 units of spend.
    let m = causal_new(100, 2, 5, 3, 10)
    // True causal effect of a unit of spend = spend_effect = 2.
    assert_eq(causal_effect_per_unit(m), 2)
    // Observational effect is INFLATED above 2 (seasonality leaks through).
    let obs = observational_effect_per_unit(m)
    assert(obs > causal_effect_per_unit(m))
}

// With NO confounding (seasonality induces no spend), do and observe AGREE —
// the back-door is closed, so correlation equals causation.
@[test]
fn test_do_and_observe_agree_without_confounding() {
    // season_on_spend = 0 → seasonality no longer drives spend.
    let m = causal_new(100, 2, 5, 0, 10)
    assert_eq(causal_effect_per_unit(m), 2)
    assert_eq(observational_effect_per_unit(m), 2)
}

// do() severs the confounder: forcing the SAME spend at different seasonality
// changes revenue ONLY through the direct season→revenue path, not through a
// spurious spend correlation. The per-unit causal effect is invariant to season.
@[test]
fn test_causal_effect_is_invariant_to_the_confounder() {
    let low = causal_new(100, 2, 5, 3, 1)
    let high = causal_new(100, 2, 5, 3, 50)
    // The lever is the same regardless of seasonality — that's what makes it a lever.
    assert_eq(causal_effect_per_unit(low), causal_effect_per_unit(high))
}

// Counterfactual: had we spent less, revenue would have been lower by exactly
// the causal effect × the spend reduction (seasonality held fixed).
@[test]
fn test_counterfactual_holds_seasonality_fixed() {
    let m = causal_new(100, 2, 5, 3, 10)
    let actual = counterfactual_revenue(m, 100)    // spent 100
    let hypo = counterfactual_revenue(m, 50)       // had we spent 50
    // Difference is purely the causal path: 2 * (100 - 50) = 100.
    assert_eq(actual - hypo, 100)
}

// do_revenue with zero forced spend isolates the confounder's direct
// contribution (base + season→revenue), with the causal path zeroed.
@[test]
fn test_do_zero_spend_leaves_only_baseline_and_direct_season() {
    let m = causal_new(100, 2, 5, 3, 10)
    // base 100 + season_on_revenue 5 * season 10 = 150.
    assert_eq(do_revenue(m, 0), 150)
}

fn main() -> i64 {
    let m = causal_new(100, 2, 5, 3, 10)
    println("── std.causal: do-calculus vs correlation ─────────────────────")
    println("model: revenue = 100 + 2*ad_spend + 5*seasonality")
    println("       (seasonality also induces 3 units of ad_spend — the confounder)")
    println("")
    let causal = causal_effect_per_unit(m)
    let observ = observational_effect_per_unit(m)
    println("CAUSAL effect per unit of ad_spend (do-calculus): {to_str(causal)}")
    println("OBSERVED effect per unit (naive correlation):     {to_str(observ)}")
    if observ > causal {
        println("→ correlation OVERSTATES the lever by {to_str(observ - causal)}x per unit")
        println("  a #[goal] without causal_model would chase the inflated number.")
    }
    println("")
    println("counterfactual: had we spent 50 instead of 100, revenue would be")
    println("  {to_str(counterfactual_revenue(m, 50))} (vs actual {to_str(counterfactual_revenue(m, 100))})")
    0
}

sources.examples/stdlib/coord.ax:
// Phase 14+ / Tier-2 stdlib: Causal ordering as type + Cross-Principal goal coordination.
//
// This module ships the two remaining Phase 14+ deliverables from ROADMAP §4:
//
//   1. CausallyOrdered — "causal ordering as type".
//      Unlike VectorClock in crdt.ax (an algorithm), CausallyOrdered is a VALUE
//      that carries its causal provenance inline: every write stamps the result
//      with the writer's node and the clock at write time, so the happens-before
//      relation is PART OF THE VALUE, not computed retroactively.
//
//      The headline contract: `co_can_read(reader_clock, item)` returns false
//      when the reader has not yet observed all writes that preceded `item`.
//      A reader that hasn't caught up to the writer's causal past must wait —
//      this is causal consistency made observable in userland.
//
//   2. CoordGoal — cross-Principal goal coordination.
//      A goal that requires a majority quorum of N principals to each
//      independently accept a candidate before it is committed. No minority
//      can force acceptance; a principal whose score is below the target
//      automatically rejects. This composes Principal + Goal + Quorum
//      semantics and closes the ROADMAP's "Cross-Principal goal coordination" item.
//
//   KEY CONTRACTS:
//   - Causal consistency: co_can_read returns false until the reader's clock
//     dominates the writer's clock (the reader has seen all prior writes).
//   - Coordination safety: coord_goal_quorum_met returns false until strictly
//     more than half of all principals have accepted the candidate.
//
//   axon test examples/stdlib/coord.ax
//   axon run  examples/stdlib/coord.ax

// ── Inlined VectorClock (from crdt.ax) ────────────────────────────────────────
// Inlined so this file is self-contained (Axon has no module imports yet).

type VClock = { cs: [i64], n: i64 }

fn vcl_new(n: i64) -> VClock { VClock { cs: arr_repeat(0, n), n: n } }

fn vcl_tick(v: VClock, node: i64) -> VClock {
    assert(node >= 0 && node < v.n)
    let out = []
    let i = 0
    while i < v.n {
        out = arr_push(out, if i == node { v.cs[i] + 1 } else { v.cs[i] })
        i = i + 1
    }
    VClock { cs: out, n: v.n }
}

fn vcl_merge(a: VClock, b: VClock) -> VClock {
    assert(a.n == b.n)
    let out = []
    let i = 0
    while i < a.n {
        out = arr_push(out, if a.cs[i] > b.cs[i] { a.cs[i] } else { b.cs[i] })
        i = i + 1
    }
    VClock { cs: out, n: a.n }
}

// a → b: a causally precedes b iff every component of a ≤ b AND at least one <.
fn vcl_before(a: VClock, b: VClock) -> bool {
    assert(a.n == b.n)
    let all_le = true
    let some_lt = false
    let i = 0
    while i < a.n {
        if a.cs[i] > b.cs[i] { all_le = false }
        if a.cs[i] < b.cs[i] { some_lt = true }
        i = i + 1
    }
    all_le && some_lt
}

fn vcl_concurrent(a: VClock, b: VClock) -> bool {
    !vcl_before(a, b) && !vcl_before(b, a)
}

// ── CausallyOrdered ────────────────────────────────────────────────────────────
// An i64 value tagged with the vector clock at the moment it was written and
// the node that wrote it.  The TIMESTAMP on the value is its causal past.

type CausallyOrdered = {
    val:    i64,
    clock:  VClock,    // the writer's clock at write time (the causal provenance)
    writer: i64,       // which node wrote this value
}

// Create a new causally-ordered value at node `writer` with initial value `v`.
// The writer ticks its own component at construction time.
fn co_new(n_nodes: i64, v: i64, writer: i64) -> CausallyOrdered {
    let clk = vcl_tick(vcl_new(n_nodes), writer)
    CausallyOrdered { val: v, clock: clk, writer: writer }
}

// Node `writer` writes a new value `v`, advancing only its own clock component.
// The new clock is the merge of the current item clock with the writer's tick —
// so it carries ALL prior causal dependencies of the original item.
fn co_write(item: CausallyOrdered, v: i64, writer: i64) -> CausallyOrdered {
    let ticked = vcl_tick(item.clock, writer)
    CausallyOrdered { val: v, clock: ticked, writer: writer }
}

// A reader with `reader_clock` may safely read `item` when its clock dominates
// the item's clock — i.e., the reader has observed everything the writer had
// seen when the write occurred (causal consistency).
fn co_can_read(reader_clock: VClock, item: CausallyOrdered) -> bool {
    // reader_clock dominates item.clock iff item.clock → reader_clock OR they are equal.
    // Equivalently: NOT (item.clock causally precedes but reader has not caught up).
    // Reader is safe iff every component of item.clock ≤ reader_clock.
    let i = 0
    let dominated = true
    while i < item.clock.n {
        if item.clock.cs[i] > reader_clock.cs[i] { dominated = false }
        i = i + 1
    }
    dominated
}

// a causally precedes b?
fn co_happens_before(a: CausallyOrdered, b: CausallyOrdered) -> bool {
    vcl_before(a.clock, b.clock)
}

// Neither a→b nor b→a? (concurrent writes)
fn co_concurrent(a: CausallyOrdered, b: CausallyOrdered) -> bool {
    vcl_concurrent(a.clock, b.clock)
}

// ── CoordGoal ──────────────────────────────────────────────────────────────────
// Cross-Principal goal coordination. N independent principals each evaluate
// a candidate and submit a score.  The goal is committed (accepted) only when
// a strict majority — ⌊n/2⌋+1 — of principals each report a score ≥ target.
//
// Safety invariant: a minority coalition cannot force acceptance no matter how
// high their scores are.  A principal that scores below `target` rejects.
//
// The consensus score is the MINIMUM accepted score (conservative: we commit
// to what every accepting principal can vouch for).

type CoordGoal = {
    target:    i64,    // minimum score each principal must reach
    n:         i64,    // total number of principals
    scores:    [i64],  // scores[i] = principal i's submitted score (0 = not yet)
    submitted: [i64],  // submitted[i] = 1 if principal i has voted, else 0
}

fn coord_goal_new(n_principals: i64, target: i64) -> CoordGoal {
    assert(n_principals > 0)
    CoordGoal {
        target:    target,
        n:         n_principals,
        scores:    arr_repeat(0, n_principals),
        submitted: arr_repeat(0, n_principals),
    }
}

// Principal `pid` submits score `score` for the current candidate.
// A principal may only submit once (idempotent: repeated submissions are ignored).
fn coord_goal_propose(cg: CoordGoal, pid: i64, score: i64) -> CoordGoal {
    assert(pid >= 0 && pid < cg.n)
    if cg.submitted[pid] == 1 {
        cg   // idempotent
    } else {
        let new_scores = []
        let new_sub    = []
        let i = 0
        while i < cg.n {
            new_scores = arr_push(new_scores, if i == pid { score } else { cg.scores[i] })
            new_sub    = arr_push(new_sub, if i == pid { 1 } else { cg.submitted[i] })
            i = i + 1
        }
        CoordGoal { target: cg.target, n: cg.n, scores: new_scores, submitted: new_sub }
    }
}

// How many principals have submitted a score ≥ target?
fn coord_goal_accept_count(cg: CoordGoal) -> i64 {
    let count = 0
    let i = 0
    while i < cg.n {
        if cg.submitted[i] == 1 && cg.scores[i] >= cg.target { count = count + 1 }
        i = i + 1
    }
    count
}

// Quorum threshold: strict majority = ⌊n/2⌋ + 1.
fn coord_goal_quorum(cg: CoordGoal) -> i64 { cg.n / 2 + 1 }

// Has the goal reached quorum? (majority of principals accepted)
fn coord_goal_quorum_met(cg: CoordGoal) -> bool {
    coord_goal_accept_count(cg) >= coord_goal_quorum(cg)
}

// Conservative consensus score: minimum accepted score across all accepting
// principals.  Only valid when quorum is met; returns -1 otherwise.
fn coord_goal_consensus_score(cg: CoordGoal) -> i64 {
    if !coord_goal_quorum_met(cg) {
        -1
    } else {
        let best = 9999999
        let i = 0
        while i < cg.n {
            if cg.submitted[i] == 1 && cg.scores[i] >= cg.target {
                if cg.scores[i] < best { best = cg.scores[i] }
            }
            i = i + 1
        }
        best
    }
}

// ════════════════════════════════════════════════════════════════════════════
//  Tests
// ════════════════════════════════════════════════════════════════════════════

// ── CausallyOrdered tests ─────────────────────────────────────────────────────

// A value written at node 0 causally precedes one written later at node 1
// (after node 1 has received node 0's write and ticked its own clock).
@[test]
fn test_co_write_establishes_causal_order() {
    let v0 = co_new(2, 10, 0)            // node 0 writes 10; clock = [1,0]
    // node 1 receives node 0's write and then writes 20:
    let v1_clock_after_recv = vcl_tick(vcl_merge(vcl_new(2), v0.clock), 1)
    let v1 = CausallyOrdered { val: 20, clock: v1_clock_after_recv, writer: 1 }
    assert(co_happens_before(v0, v1))
    assert(!co_happens_before(v1, v0))
}

// Two concurrent writes (neither has seen the other's clock) are concurrent.
@[test]
fn test_co_concurrent_writes_are_concurrent() {
    let a = co_new(2, 10, 0)    // clock = [1,0]
    let b = co_new(2, 20, 1)    // clock = [0,1]
    assert(co_concurrent(a, b))
    assert(!co_happens_before(a, b))
    assert(!co_happens_before(b, a))
}

// A reader whose clock dominates the item's clock CAN read it safely.
@[test]
fn test_co_can_read_when_reader_dominates() {
    let item = co_new(2, 42, 0)          // item clock = [1,0]
    // A reader that has seen node 0's write: clock = [1,1] (dominates [1,0]).
    let reader_clock = vcl_tick(vcl_tick(vcl_new(2), 0), 1)
    assert(co_can_read(reader_clock, item))
}

// A reader whose clock does NOT yet cover the item's provenance CANNOT safely read.
@[test]
fn test_co_cannot_read_stale_reader() {
    let item = co_new(2, 42, 0)      // item clock = [1,0]
    let stale_reader = vcl_new(2)    // reader clock = [0,0] — hasn't seen node 0's write
    assert(!co_can_read(stale_reader, item))
}

// A write advances only the writing node's clock component; other components
// propagate the original item's causal history.
@[test]
fn test_co_write_advances_writer_clock() {
    let v0 = co_new(3, 10, 0)        // [1,0,0]
    let v1 = co_write(v0, 20, 1)     // writer=1, clock = merge([1,0,0], tick(1)) = [1,1,0]
    assert(v1.val == 20)
    assert(v1.writer == 1)
    // v0 causally precedes v1 (v0's clock [1,0,0] → v1's clock [1,1,0])
    assert(co_happens_before(v0, v1))
}

// ── CoordGoal tests ────────────────────────────────────────────────────────────

// A freshly created coordination goal has no submissions and quorum is not met.
@[test]
fn test_coord_goal_starts_unmet() {
    let cg = coord_goal_new(3, 80)
    assert(!coord_goal_quorum_met(cg))
    assert_eq(coord_goal_accept_count(cg), 0)
    assert_eq(coord_goal_consensus_score(cg), -1)
}

// Quorum threshold for 3 principals is 2 (⌊3/2⌋+1 = 2).
@[test]
fn test_coord_goal_quorum_threshold() {
    assert_eq(coord_goal_quorum(coord_goal_new(3, 80)), 2)
    assert_eq(coord_goal_quorum(coord_goal_new(5, 80)), 3)
    assert_eq(coord_goal_quorum(coord_goal_new(1, 80)), 1)
}

// 1 out of 3 principals accepting does NOT meet quorum.
@[test]
fn test_coord_goal_minority_cannot_commit() {
    let cg = coord_goal_new(3, 80)
    let cg2 = coord_goal_propose(cg, 0, 95)    // principal 0 accepts (score ≥ 80)
    assert(!coord_goal_quorum_met(cg2))
    assert_eq(coord_goal_accept_count(cg2), 1)
}

// 2 out of 3 principals accepting DOES meet quorum.
@[test]
fn test_coord_goal_majority_commits() {
    let cg = coord_goal_new(3, 80)
    let cg2 = coord_goal_propose(coord_goal_propose(cg, 0, 95), 1, 88)
    assert(coord_goal_quorum_met(cg2))
    assert_eq(coord_goal_accept_count(cg2), 2)
}

// Consensus score is the minimum across accepting principals (conservative).
@[test]
fn test_coord_goal_consensus_is_minimum_accepted() {
    let cg = coord_goal_new(3, 80)
    let cg2 = coord_goal_propose(coord_goal_propose(cg, 0, 95), 1, 88)
    // min(95, 88) = 88
    assert_eq(coord_goal_consensus_score(cg2), 88)
}

// A principal that scores BELOW target does not count as accepted.
@[test]
fn test_coord_goal_below_target_does_not_count() {
    let cg = coord_goal_new(3, 80)
    let cg2 = coord_goal_propose(coord_goal_propose(cg, 0, 50), 1, 60)  // both below 80
    assert(!coord_goal_quorum_met(cg2))
    assert_eq(coord_goal_accept_count(cg2), 0)
}

// Proposals are idempotent: a second proposal from the same principal is ignored.
@[test]
fn test_coord_goal_proposal_is_idempotent() {
    let cg = coord_goal_new(3, 80)
    let cg2 = coord_goal_propose(cg, 0, 95)
    let cg3 = coord_goal_propose(cg2, 0, 50)    // same pid; should be ignored
    assert_eq(cg3.scores[0], 95)                 // first score kept
    assert_eq(coord_goal_accept_count(cg3), 1)
}

// All 3 principals accept → quorum still met; consensus is the minimum.
@[test]
fn test_coord_goal_full_consensus() {
    let cg = coord_goal_new(3, 80)
    let cg2 = coord_goal_propose(
        coord_goal_propose(coord_goal_propose(cg, 0, 90), 1, 85), 2, 92)
    assert(coord_goal_quorum_met(cg2))
    assert_eq(coord_goal_accept_count(cg2), 3)
    assert_eq(coord_goal_consensus_score(cg2), 85)
}

// ── Cross-Principal safety headline test ──────────────────────────────────────
// Two principals (Alice and Bob) optimize a shared goal with target=80.
// Alice proposes score=90 (accepts) but Bob proposes score=70 (rejects).
// Since only 1/2 principals meet the target, quorum is NOT met and the goal
// is NOT committed — a majority is required, safety is preserved.
@[test]
fn test_cross_principal_minority_cannot_override_safety() {
    // 2 principals, target=80: quorum threshold = ⌊2/2⌋+1 = 2 (unanimous)
    let goal = coord_goal_new(2, 80)
    let alice_id = 0
    let bob_id   = 1
    let after_alice = coord_goal_propose(goal, alice_id, 90)   // accepts
    let after_bob   = coord_goal_propose(after_alice, bob_id, 70)  // rejects (< 80)
    assert_eq(coord_goal_accept_count(after_bob), 1)
    assert(!coord_goal_quorum_met(after_bob))
    // Even though Alice scored 90, Bob's rejection prevents commitment.
    assert_eq(coord_goal_consensus_score(after_bob), -1)
}

fn main() -> i64 {
    println("── coord: causal ordering as type ─────────────────────────────")
    let n = 2
    let v0 = co_new(n, 10, 0)
    let v1 = co_write(v0, 20, 1)
    println("node 0 writes 10, then node 1 writes 20 (after receiving node 0's write)")
    if co_happens_before(v0, v1) {
        println("→ v0 causally precedes v1 (correct causal order)")
    }
    let stale = vcl_new(n)
    let up_to_date = vcl_merge(v0.clock, vcl_tick(vcl_new(n), 1))
    if !co_can_read(stale, v0) {
        println("→ stale reader cannot safely read v0 (causal consistency enforced)")
    }
    if co_can_read(up_to_date, v0) {
        println("→ up-to-date reader can safely read v0")
    }
    println("")
    println("── coord: cross-principal goal coordination ────────────────────")
    let cg = coord_goal_new(3, 80)
    let cg2 = coord_goal_propose(coord_goal_propose(cg, 0, 90), 1, 85)
    if !coord_goal_quorum_met(cg2) {
        println("1/3 principals accepted — quorum not yet met")
    }
    let cg3 = coord_goal_propose(cg2, 2, 88)
    if coord_goal_quorum_met(cg3) {
        let score = coord_goal_consensus_score(cg3)
        println("3/3 principals accepted — goal committed, consensus score {to_str(score)}")
    }
    0
}

