// Phase 14 Slice 2 / Tier-2 stdlib: Replicated<T> and Quorum<T>.
//
// Replicated<T> — Eventually-consistent replicated value (LWW semantics).
//   Any node may write at any time; after convergence every node agrees.
//   Properties: commutativity, idempotency, associativity of merge.
//
// Quorum<T> — Majority-quorum write/read (linearizable safety).
//   A write commits only when ⌊n/2⌋+1 replicas acknowledge it.
//   Safety: no two different values can both achieve quorum at the same
//   timestamp — they cannot both collect a majority simultaneously.
//
// These are the Tier-2 Store constructors from ROADMAP §4 Phase 14 ("Slice 2")
// that complement the CRDT types in crdt.ax (Slice 1).
//
// Implementation note: Axon's arr_push is concretely typed for i64, so
// Replicated stores parallel [i64] arrays (vals, timestamps) per node rather
// than an array of structs — the same pattern used in crdt.ax.
//
//   axon test examples/stdlib/replicated.ax   # run @[test]s
//   axon run  examples/stdlib/replicated.ax   # demo

// ── Replicated<T> ─────────────────────────────────────────────────────────────
// An i64 value replicated across N nodes using LWW (last-write-wins) semantics.
// Each node owns an independent (val, ts) slot; ts is a logical timestamp.
// Nodes write without coordination; convergence is guaranteed once every
// replica has seen every write.

type Replicated = { vals: [i64], timestamps: [i64], n: i64 }

fn replicated_new(n_nodes: i64, initial_val: i64) -> Replicated {
    assert(n_nodes > 0)
    Replicated {
        vals:       arr_repeat(initial_val, n_nodes),
        timestamps: arr_repeat(0, n_nodes),
        n:          n_nodes,
    }
}

// Record a write on `node` at logical timestamp `ts`.
// Silently ignored when ts does not exceed the node's current timestamp
// (stale write; LWW semantics).
fn replicated_write(r: Replicated, node: i64, val: i64, ts: i64) -> Replicated {
    assert(node >= 0 && node < r.n)
    let cur_ts = r.timestamps[node]
    if ts <= cur_ts {
        r
    } else {
        let new_vals = []
        let new_ts   = []
        let i = 0
        while i < r.n {
            new_vals = arr_push(new_vals, if i == node { val } else { r.vals[i] })
            new_ts   = arr_push(new_ts,   if i == node { ts  } else { r.timestamps[i] })
            i = i + 1
        }
        Replicated { vals: new_vals, timestamps: new_ts, n: r.n }
    }
}

// Sync: node `dst` learns what node `src` knows (one-way LWW merge).
fn replicated_sync(r: Replicated, dst: i64, src: i64) -> Replicated {
    assert(dst >= 0 && dst < r.n)
    assert(src >= 0 && src < r.n)
    let src_val = r.vals[src]
    let src_ts  = r.timestamps[src]
    replicated_write(r, dst, src_val, src_ts)
}

// Converge: broadcast the global winner (highest-ts, tie-break = highest val)
// to every node.  After this call all nodes agree.
fn replicated_converge(r: Replicated) -> Replicated {
    let best_val = r.vals[0]
    let best_ts  = r.timestamps[0]
    let i = 1
    while i < r.n {
        let ts = r.timestamps[i]
        let v  = r.vals[i]
        if ts > best_ts || (ts == best_ts && v > best_val) {
            best_val = v
            best_ts  = ts
        }
        i = i + 1
    }
    Replicated {
        vals:       arr_repeat(best_val, r.n),
        timestamps: arr_repeat(best_ts, r.n),
        n:          r.n,
    }
}

// Read node's current (local) view.
fn replicated_read(r: Replicated, node: i64) -> i64 {
    assert(node >= 0 && node < r.n)
    r.vals[node]
}

// True iff all nodes agree on the same value.
fn replicated_converged(r: Replicated) -> bool {
    let v0 = r.vals[0]
    let ok = true
    let i = 1
    while i < r.n {
        if r.vals[i] != v0 { ok = false }
        i = i + 1
    }
    ok
}

// ── Quorum<T> ─────────────────────────────────────────────────────────────────
// Linearizable write/read via majority quorum.
//
// quorum_new(n)          — n replicas, quorum_size = n/2 + 1.
// quorum_propose(q,v,ts) — open a pending proposal for value v.
//                          Rejected (Err) if ts ≤ committed_ts.
// quorum_ack(q,ts)       — a replica acknowledges the pending proposal.
//                          Ignored if ts ≠ pending_ts.
// quorum_try_commit(q)   — commit if pending_acks ≥ quorum_size.
// quorum_read(q)         — Ok(v) iff committed, else Err.
//
// Safety invariant: no two different values at the same ts can both collect
// a majority (pigeonhole: each replica can vote for only one ts at a time,
// so two majority-sets must overlap, producing a contradiction).

type Quorum = {
    n:             i64,
    quorum_size:   i64,
    pending_val:   i64,
    pending_ts:    i64,
    pending_acks:  i64,
    committed_val: i64,
    committed_ts:  i64,
    committed:     bool,
}

fn quorum_new(n_nodes: i64) -> Quorum {
    assert(n_nodes > 0)
    Quorum {
        n:             n_nodes,
        quorum_size:   n_nodes / 2 + 1,
        pending_val:   0,
        pending_ts:    -1,
        pending_acks:  0,
        committed_val: 0,
        committed_ts:  -1,
        committed:     false,
    }
}

// Propose a new write.  Returns Err if the proposal is stale (ts ≤ committed_ts).
fn quorum_propose(q: Quorum, val: i64, ts: i64) -> Result<Quorum, str> {
    if ts <= q.committed_ts {
        Err("stale proposal: ts must be strictly greater than committed_ts")
    } else {
        Ok(Quorum {
            n:             q.n,
            quorum_size:   q.quorum_size,
            pending_val:   val,
            pending_ts:    ts,
            pending_acks:  0,
            committed_val: q.committed_val,
            committed_ts:  q.committed_ts,
            committed:     q.committed,
        })
    }
}

// Simulate one replica acknowledging the pending proposal.
// Ignored when ts ≠ pending_ts (ack is for an outdated round).
fn quorum_ack(q: Quorum, ts: i64) -> Quorum {
    if ts == q.pending_ts {
        Quorum {
            n:             q.n,
            quorum_size:   q.quorum_size,
            pending_val:   q.pending_val,
            pending_ts:    q.pending_ts,
            pending_acks:  q.pending_acks + 1,
            committed_val: q.committed_val,
            committed_ts:  q.committed_ts,
            committed:     q.committed,
        }
    } else {
        q
    }
}

// Commit the pending proposal if enough acks have been collected and the
// pending ts strictly exceeds the already-committed ts (monotone writes).
fn quorum_try_commit(q: Quorum) -> Quorum {
    if q.pending_acks >= q.quorum_size && q.pending_ts > q.committed_ts {
        Quorum {
            n:             q.n,
            quorum_size:   q.quorum_size,
            pending_val:   q.pending_val,
            pending_ts:    q.pending_ts,
            pending_acks:  q.pending_acks,
            committed_val: q.pending_val,
            committed_ts:  q.pending_ts,
            committed:     true,
        }
    } else {
        q
    }
}

// Read the committed value, or Err if no write has committed yet.
fn quorum_read(q: Quorum) -> Result<i64, str> {
    if q.committed { Ok(q.committed_val) } else { Err("no committed value") }
}

// ── Test helpers ──────────────────────────────────────────────────────────────

fn propose_ok(q: Quorum, val: i64, ts: i64) -> Quorum {
    match quorum_propose(q, val, ts) {
        Ok(q2) => q2
        Err(_) => { assert(false)  quorum_new(1) }
    }
}

fn read_ok(q: Quorum) -> i64 {
    match quorum_read(q) {
        Ok(v)  => v
        Err(_) => { assert(false)  0 }
    }
}

// ══════════════════════════════════════════════════════════════════════════════
//  Tests
// ══════════════════════════════════════════════════════════════════════════════

// ── Replicated tests ──────────────────────────────────────────────────────────

@[test]
fn test_replicated_write_visible_to_local_node() {
    let r = replicated_new(3, 0)
    let r = replicated_write(r, 0, 42, 1)
    assert_eq(replicated_read(r, 0), 42)
    assert_eq(replicated_read(r, 1), 0)   // other nodes unaffected
    assert_eq(replicated_read(r, 2), 0)
}

@[test]
fn test_replicated_higher_ts_wins_on_same_node() {
    let r = replicated_new(2, 0)
    let r = replicated_write(r, 0, 99, 3)
    let r = replicated_write(r, 0, 7,  1)   // stale ts — ignored
    assert_eq(replicated_read(r, 0), 99)
}

@[test]
fn test_replicated_sync_propagates_newest_write() {
    let r = replicated_new(3, 0)
    let r = replicated_write(r, 0, 42, 5)
    let r = replicated_write(r, 1, 99, 3)   // ts=3 < ts=5
    // node 1 learns from node 0 → node 0's write (ts=5) should win
    let r = replicated_sync(r, 1, 0)
    assert_eq(replicated_read(r, 1), 42)
}

@[test]
fn test_replicated_not_converged_after_concurrent_writes() {
    let r = replicated_new(3, 0)
    let r = replicated_write(r, 0, 10, 3)
    let r = replicated_write(r, 1, 20, 7)
    let r = replicated_write(r, 2, 15, 5)
    assert(!replicated_converged(r))
}

@[test]
fn test_replicated_converge_all_nodes_agree() {
    let r = replicated_new(3, 0)
    let r = replicated_write(r, 0, 10, 3)
    let r = replicated_write(r, 1, 20, 7)   // highest ts → wins
    let r = replicated_write(r, 2, 15, 5)
    let r = replicated_converge(r)
    assert(replicated_converged(r))
    assert_eq(replicated_read(r, 0), 20)
    assert_eq(replicated_read(r, 1), 20)
    assert_eq(replicated_read(r, 2), 20)
}

@[test]
fn test_replicated_tie_break_is_deterministic() {
    // Same ts, different values → higher value wins on every node.
    let r = replicated_new(2, 0)
    let r = replicated_write(r, 0, 50, 5)
    let r = replicated_write(r, 1, 99, 5)
    let r = replicated_converge(r)
    assert_eq(replicated_read(r, 0), 99)
    assert_eq(replicated_read(r, 1), 99)
}

@[test]
fn test_replicated_convergence_is_commutative() {
    // Sync in different orders must produce the same converged value.
    let r = replicated_new(2, 0)
    let r = replicated_write(r, 0, 100, 10)
    let r = replicated_write(r, 1, 200, 20)
    // path 1: sync 0←1, then 1←0
    let r1 = replicated_converge(replicated_sync(replicated_sync(r, 0, 1), 1, 0))
    // path 2: sync 1←0, then 0←1
    let r2 = replicated_converge(replicated_sync(replicated_sync(r, 1, 0), 0, 1))
    assert_eq(replicated_read(r1, 0), replicated_read(r2, 0))
    assert_eq(replicated_read(r1, 1), replicated_read(r2, 1))
}

@[test]
fn test_replicated_converge_is_idempotent() {
    let r = replicated_new(2, 0)
    let r = replicated_write(r, 0, 7, 1)
    let r = replicated_write(r, 1, 3, 2)
    let r1 = replicated_converge(r)
    let r2 = replicated_converge(r1)
    assert_eq(replicated_read(r1, 0), replicated_read(r2, 0))
    assert_eq(replicated_read(r1, 1), replicated_read(r2, 1))
}

// ── Quorum tests ──────────────────────────────────────────────────────────────

@[test]
fn test_quorum_size_is_majority() {
    assert_eq(quorum_new(1).quorum_size, 1)
    assert_eq(quorum_new(2).quorum_size, 2)
    assert_eq(quorum_new(3).quorum_size, 2)
    assert_eq(quorum_new(5).quorum_size, 3)
    assert_eq(quorum_new(7).quorum_size, 4)
}

@[test]
fn test_quorum_read_uncommitted_returns_err() {
    let q = quorum_new(3)
    match quorum_read(q) {
        Ok(_)  => assert(false)
        Err(_) => assert(true)
    }
}

@[test]
fn test_quorum_commits_after_majority_acks() {
    let q = quorum_new(3)              // quorum_size = 2
    let q = propose_ok(q, 42, 1)
    let q = quorum_ack(q, 1)
    let q = quorum_ack(q, 1)          // 2 acks → majority reached
    let q = quorum_try_commit(q)
    assert(q.committed)
    assert_eq(read_ok(q), 42)
}

@[test]
fn test_quorum_does_not_commit_below_majority() {
    let q = quorum_new(3)              // quorum_size = 2
    let q = propose_ok(q, 99, 1)
    let q = quorum_ack(q, 1)          // only 1 ack — not enough
    let q = quorum_try_commit(q)
    assert(!q.committed)
    match quorum_read(q) {
        Ok(_)  => assert(false)
        Err(_) => assert(true)
    }
}

@[test]
fn test_quorum_five_nodes_needs_three_acks() {
    let q = quorum_new(5)              // quorum_size = 3
    let q = propose_ok(q, 77, 1)
    let q = quorum_ack(q, 1)
    let q = quorum_ack(q, 1)
    // 2 acks — still short
    let q2 = quorum_try_commit(q)
    assert(!q2.committed)
    // 3rd ack → commits
    let q = quorum_ack(q, 1)
    let q = quorum_try_commit(q)
    assert(q.committed)
    assert_eq(read_ok(q), 77)
}

@[test]
fn test_quorum_stale_proposal_is_rejected() {
    let q = quorum_new(3)
    let q = propose_ok(q, 1, 10)
    let q = quorum_ack(q, 10)
    let q = quorum_ack(q, 10)
    let q = quorum_try_commit(q)        // committed at ts=10
    match quorum_propose(q, 999, 5) {   // ts=5 is stale
        Ok(_)  => assert(false)
        Err(_) => assert(true)
    }
}

@[test]
fn test_quorum_ack_for_wrong_ts_is_ignored() {
    let q = quorum_new(3)
    let q = propose_ok(q, 55, 10)
    let q = quorum_ack(q, 99)           // wrong ts → no effect
    assert_eq(q.pending_acks, 0)
}

// Safety: once a value commits, a competing proposal at the same ts is stale.
// (Demonstrates the pigeon-hole property without live networking.)
@[test]
fn test_quorum_safety_committed_blocks_stale_proposal() {
    let q = quorum_new(5)               // quorum_size = 3
    let q = propose_ok(q, 100, 1)
    let q = quorum_ack(q, 1)
    let q = quorum_ack(q, 1)
    let q = quorum_ack(q, 1)
    let q = quorum_try_commit(q)
    assert(q.committed)
    assert_eq(read_ok(q), 100)
    // A proposal at ts=1 is now stale (committed_ts=1) → rejected
    match quorum_propose(q, 200, 1) {
        Ok(_)  => assert(false)
        Err(_) => assert(true)
    }
}

@[test]
fn test_quorum_second_write_succeeds_at_higher_ts() {
    let q = quorum_new(3)
    let q = propose_ok(q, 10, 1)
    let q = quorum_ack(q, 1)
    let q = quorum_ack(q, 1)
    let q = quorum_try_commit(q)
    assert_eq(read_ok(q), 10)
    // A new write at ts=2 succeeds and updates the committed value
    let q = propose_ok(q, 20, 2)
    let q = quorum_ack(q, 2)
    let q = quorum_ack(q, 2)
    let q = quorum_try_commit(q)
    assert_eq(read_ok(q), 20)
}

// ── Demo ──────────────────────────────────────────────────────────────────────

fn main() -> i64 {
    println("── Replicated<T> demo ────────────────────────────────────────────")
    println("")
    println("3-node replicated register — concurrent writes, then converge:")
    let r = replicated_new(3, 0)
    let r = replicated_write(r, 0, 10, 3)
    let r = replicated_write(r, 1, 20, 7)
    let r = replicated_write(r, 2, 15, 5)
    println("  node-0 sees: {to_str(replicated_read(r, 0))}  (wrote 10 @ ts=3)")
    println("  node-1 sees: {to_str(replicated_read(r, 1))}  (wrote 20 @ ts=7)")
    println("  node-2 sees: {to_str(replicated_read(r, 2))}  (wrote 15 @ ts=5)")
    let r = replicated_converge(r)
    println("  after converge: all nodes see {to_str(replicated_read(r, 0))}  (ts=7 wins)")

    println("")
    println("── Quorum<T> demo ────────────────────────────────────────────────")
    println("")
    println("3-node quorum (quorum_size=2) — write commits after 2 acks:")
    let q = quorum_new(3)
    let q = match quorum_propose(q, 42, 1) { Ok(q2) => q2  Err(_) => quorum_new(1) }
    let q = quorum_ack(q, 1)
    let q = quorum_ack(q, 1)
    let q = quorum_try_commit(q)
    match quorum_read(q) {
        Ok(v)  => println("  committed value: {to_str(v)} (2/3 acks)")
        Err(e) => println("  not committed: {e}")
    }

    println("")
    println("5-node quorum — stale proposal rejected after commit:")
    let q2 = quorum_new(5)
    let q2 = match quorum_propose(q2, 100, 10) { Ok(q3) => q3  Err(_) => quorum_new(1) }
    let q2 = quorum_ack(q2, 10)
    let q2 = quorum_ack(q2, 10)
    let q2 = quorum_ack(q2, 10)
    let q2 = quorum_try_commit(q2)
    match quorum_propose(q2, 200, 5) {
        Ok(_)  => println("  ERROR: stale proposal accepted")
        Err(e) => println("  stale write at ts=5 rejected: {e}")
    }
    0
}

sources.examples/stdlib/risk.ax:
// Tier-1 stdlib: Risk — derived risk classification + simulation pipeline gate.
//
// ROADMAP §4 Phase 11: "Risk is *derived* from effect rows + budget magnitude +
// irreversibility annotation (users may raise, not lower); Risk ≥ High automatically
// triggers simulate → stress → redteam → verify → deploy; rejection at any gate
// halts the deploy."
//
// Risk levels are ordered integers (Low < Medium < High < Critical) so callers can
// compare them with >= / <= without a match table. The derivation rules are:
//
//   Effect rows:
//     exec present              → at least Critical
//     net + fs_write present    → at least High
//     net or fs_write present   → at least Medium
//     pure (empty row)          → Low
//   Budget magnitude (burn %):
//     >= 80 %                   → at least Critical
//     >= 50 %                   → at least High
//     >= 25 %                   → at least Medium
//   Irreversibility annotation:
//     true                      → raise by one level (clamped at Critical)
//
//   Final risk = max(effects_risk, budget_risk, irreversible_raise(base))
//   Users MAY raise risk (never lower) via `risk_raise`.
//
// Pipeline gate (the Phase-11 forcing function):
//   Risk < High  → skip simulation, run deploy directly.
//   Risk >= High → simulate → stress → redteam → verify → deploy in sequence;
//                  rejection at any gate halts the run (returns failure).
//
//   axon test examples/stdlib/risk.ax
//   axon run  examples/stdlib/risk.ax

// ── Risk levels ──────────────────────────────────────────────────────────────

fn risk_low() -> i64 { 0 }
fn risk_medium() -> i64 { 1 }
fn risk_high() -> i64 { 2 }
fn risk_critical() -> i64 { 3 }

fn risk_name(r: i64) -> str {
    if r <= 0 { "Low" } else {
        if r == 1 { "Medium" } else {
            if r == 2 { "High" } else { "Critical" }
        }
    }
}

// Users may raise risk, but not lower it (monotone-up).
fn risk_raise(current: i64, floor: i64) -> i64 {
    if floor > current { floor } else { current }
}

fn risk_clamp(r: i64) -> i64 {
    clamp_i64(r, risk_low(), risk_critical())
}

// ── Risk derivation ──────────────────────────────────────────────────────────
//
// Effect bits must match the ef_* constants in effect.ax:
//   fs_read=1, fs_write=2, net=4, exec=8
// Callers pass the ef_union / ef_add result from their effect set.

fn risk_from_effects(effect_set: i64) -> i64 {
    let exec_bit = 8
    let net_bit = 4
    let fs_write_bit = 2
    let has_exec = bit_and(effect_set, exec_bit) != 0
    let has_net = bit_and(effect_set, net_bit) != 0
    let has_fs_write = bit_and(effect_set, fs_write_bit) != 0
    if has_exec { risk_critical() } else {
        if has_net && has_fs_write { risk_high() } else {
            if has_net || has_fs_write { risk_medium() } else { risk_low() }
        }
    }
}

// budget_burn_pct = (used * 100 / cap), clamped 0..100.
fn risk_from_budget(budget_burn_pct: i64) -> i64 {
    if budget_burn_pct >= 80 { risk_critical() } else {
        if budget_burn_pct >= 50 { risk_high() } else {
            if budget_burn_pct >= 25 { risk_medium() } else { risk_low() }
        }
    }
}

// Irreversibility raises risk by one level (clamped at Critical).
fn risk_from_irreversibility(base: i64, irreversible: bool) -> i64 {
    if irreversible { risk_clamp(base + 1) } else { base }
}

// Combine all three axes — max wins.
fn risk_derive(effect_set: i64, budget_burn_pct: i64, irreversible: bool) -> i64 {
    let er = risk_from_effects(effect_set)
    let br = risk_from_budget(budget_burn_pct)
    let base = max_i64(er, br)
    risk_from_irreversibility(base, irreversible)
}

fn risk_requires_pipeline(r: i64) -> bool {
    r >= risk_high()
}

// ── GateResult ───────────────────────────────────────────────────────────────
//
// Each pipeline gate returns a (passed, reason) pair.  A GateResult value
// packs both into a struct so callers can inspect failures without exceptions.

type GateResult = { passed: bool, reason: str }

fn gate_pass() -> GateResult {
    GateResult { passed: true, reason: "ok" }
}

fn gate_fail(reason: str) -> GateResult {
    GateResult { passed: false, reason: reason }
}

// ── Pipeline stages ──────────────────────────────────────────────────────────
//
// Each stage is a function ()-> GateResult (modelled here as concrete helpers
// that callers substitute with their own logic).  The pipeline stops at the first
// gate that fails.

type PipelineResult = {
    stage_reached: i64,   // 0=none, 1=sim, 2=stress, 3=redteam, 4=verify, 5=deploy
    deployed: bool,
    failed_stage: str,
    failed_reason: str,
}

fn pipeline_ok() -> PipelineResult {
    PipelineResult {
        stage_reached: 5,
        deployed: true,
        failed_stage: "none",
        failed_reason: "none",
    }
}

fn pipeline_halted(stage: str, reason: str, reached: i64) -> PipelineResult {
    PipelineResult {
        stage_reached: reached,
        deployed: false,
        failed_stage: stage,
        failed_reason: reason,
    }
}

// Run a Risk-gated deploy pipeline given five gate callbacks.
// If Risk < High the simulate/stress/redteam stages are skipped; only verify → deploy run.
// The deploy fn is called only if all preceding gates pass.
fn pipeline_run(
    risk: i64,
    sim_result: GateResult,
    stress_result: GateResult,
    redteam_result: GateResult,
    verify_result: GateResult,
    deploy_result: GateResult
) -> PipelineResult {
    if risk_requires_pipeline(risk) {
        // simulate gate
        if !sim_result.passed {
            pipeline_halted("simulate", sim_result.reason, 1)
        } else {
            // stress gate
            if !stress_result.passed {
                pipeline_halted("stress", stress_result.reason, 2)
            } else {
                // redteam gate
                if !redteam_result.passed {
                    pipeline_halted("redteam", redteam_result.reason, 3)
                } else {
                    // verify gate
                    if !verify_result.passed {
                        pipeline_halted("verify", verify_result.reason, 4)
                    } else {
                        // deploy gate
                        if !deploy_result.passed {
                            pipeline_halted("deploy", deploy_result.reason, 5)
                        } else {
                            pipeline_ok()
                        }
                    }
                }
            }
        }
    } else {
        // Low / Medium risk: only verify → deploy
        if !verify_result.passed {
            pipeline_halted("verify", verify_result.reason, 4)
        } else {
            if !deploy_result.passed {
                pipeline_halted("deploy", deploy_result.reason, 5)
            } else {
                pipeline_ok()
            }
        }
    }
}

fn pipeline_summary(p: PipelineResult) -> str {
    if p.deployed {
        "deployed ✓"
    } else {
        "HALTED at {p.failed_stage}: {p.failed_reason}"
    }
}

// ── Tests ────────────────────────────────────────────────────────────────────

@[test]
fn test_risk_levels_are_ordered() {
    assert(risk_low() < risk_medium())
    assert(risk_medium() < risk_high())
    assert(risk_high() < risk_critical())
}

@[test]
fn test_risk_names() {
    assert_eq_str(risk_name(risk_low()), "Low")
    assert_eq_str(risk_name(risk_medium()), "Medium")
    assert_eq_str(risk_name(risk_high()), "High")
    assert_eq_str(risk_name(risk_critical()), "Critical")
}

@[test]
fn test_risk_raise_is_monotone_up() {
    assert_eq(risk_raise(risk_low(), risk_medium()), risk_medium())  // raised
    assert_eq(risk_raise(risk_high(), risk_low()), risk_high())      // not lowered
    assert_eq(risk_raise(risk_high(), risk_high()), risk_high())     // unchanged
}

@[test]
fn test_risk_from_effects() {
    let pure_set = 0
    let net_bit = 4
    let fs_write_bit = 2
    let exec_bit = 8
    assert_eq(risk_from_effects(pure_set), risk_low())
    assert_eq(risk_from_effects(net_bit), risk_medium())
    assert_eq(risk_from_effects(fs_write_bit), risk_medium())
    assert_eq(risk_from_effects(bit_or(net_bit, fs_write_bit)), risk_high())
    assert_eq(risk_from_effects(exec_bit), risk_critical())
}

@[test]
fn test_risk_from_budget() {
    assert_eq(risk_from_budget(10), risk_low())
    assert_eq(risk_from_budget(30), risk_medium())
    assert_eq(risk_from_budget(60), risk_high())
    assert_eq(risk_from_budget(85), risk_critical())
}

@[test]
fn test_irreversibility_raises_by_one() {
    assert_eq(risk_from_irreversibility(risk_low(), true), risk_medium())
    assert_eq(risk_from_irreversibility(risk_high(), true), risk_critical())
    // Clamped at Critical
    assert_eq(risk_from_irreversibility(risk_critical(), true), risk_critical())
    // false: no change
    assert_eq(risk_from_irreversibility(risk_medium(), false), risk_medium())
}

@[test]
fn test_risk_derive_max_wins() {
    // Pure effects, low budget, reversible → Low
    assert_eq(risk_derive(0, 10, false), risk_low())
    // Exec effect dominates everything else
    assert_eq(risk_derive(8, 10, false), risk_critical())
    // Budget 60% + net → High (budget wins over net alone = Medium)
    let net = 4
    assert_eq(risk_derive(net, 60, false), risk_high())
    // Pure + irreversible → Medium
    assert_eq(risk_derive(0, 10, true), risk_medium())
}

@[test]
fn test_requires_pipeline_threshold() {
    assert(!risk_requires_pipeline(risk_low()))
    assert(!risk_requires_pipeline(risk_medium()))
    assert(risk_requires_pipeline(risk_high()))
    assert(risk_requires_pipeline(risk_critical()))
}

@[test]
fn test_pipeline_low_risk_skips_sim_stages() {
    // Low risk: all gates pass except simulate (but sim is skipped)
    let r = pipeline_run(
        risk_low(),
        gate_fail("sim would have blocked"),  // skipped — risk < High
        gate_fail("stress would have blocked"),
        gate_fail("redteam would have blocked"),
        gate_pass(),   // verify ok
        gate_pass()    // deploy ok
    )
    assert(r.deployed)
}

@[test]
fn test_pipeline_high_risk_runs_all_gates() {
    // High risk: simulate fails → halt at simulate
    let r = pipeline_run(
        risk_high(),
        gate_fail("simulation diverges from prod"),
        gate_pass(),
        gate_pass(),
        gate_pass(),
        gate_pass()
    )
    assert(!r.deployed)
    assert_eq_str(r.failed_stage, "simulate")
}

@[test]
fn test_pipeline_halts_at_first_failure() {
    // High risk, simulate passes, stress fails
    let r = pipeline_run(
        risk_high(),
        gate_pass(),
        gate_fail("latency SLO violated under stress"),
        gate_pass(),
        gate_pass(),
        gate_pass()
    )
    assert(!r.deployed)
    assert_eq_str(r.failed_stage, "stress")
    assert_eq(r.stage_reached, 2)
}

// The LAST TWO gates before a deploy were the only ones with no failure test.
// A mutation sweep over this file flipped `if !verify_result.passed` and
// `if !deploy_result.passed` to `false` — "never fail on verify", "never fail
// on deploy" — on BOTH the high-risk chain and the low/medium short path, and
// all four mutants survived the suite. So a change that stopped honouring
// either gate would have shipped green, on the one function whose whole job is
// to stop a deploy.

@[test]
fn test_summary_does_not_report_a_halt_as_a_deploy() {
    // `pipeline_summary` is the only thing a human reads. Both of its branches
    // survived mutation — it could have reported "deployed" for a halted
    // pipeline and nothing would have failed, which is the reporting-layer
    // version of the bug this whole function exists to prevent.
    let halted = pipeline_run(
        risk_high(),
        gate_fail("sim diverges"),
        gate_pass(),
        gate_pass(),
        gate_pass(),
        gate_pass()
    )
    assert(!str_contains(pipeline_summary(halted), "deployed"))
    assert(str_contains(pipeline_summary(halted), "HALTED"))
    assert(str_contains(pipeline_summary(halted), "simulate"))

    let ok = pipeline_run(
        risk_low(),
        gate_pass(),
        gate_pass(),
        gate_pass(),
        gate_pass(),
        gate_pass()
    )
    assert(str_contains(pipeline_summary(ok), "deployed"))
    assert(!str_contains(pipeline_summary(ok), "HALTED"))
}

@[test]
fn test_pipeline_halts_at_verify() {
    // High risk: everything upstream passes, verify fails.
    let r = pipeline_run(
        risk_high(),
        gate_pass(),
        gate_pass(),
        gate_pass(),
        gate_fail("postcondition unproven"),
        gate_pass()
    )
    assert(!r.deployed)
    assert_eq_str(r.failed_stage, "verify")
    assert_eq(r.stage_reached, 4)
}

@[test]
fn test_pipeline_halts_at_deploy() {
    // High risk: every gate passes and the deploy step itself fails. Reaching
    // the last gate must still be able to stop the deploy.
    let r = pipeline_run(
        risk_critical(),
        gate_pass(),
        gate_pass(),
        gate_pass(),
        gate_pass(),
        gate_fail("target cluster unreachable")
    )
    assert(!r.deployed)
    assert_eq_str(r.failed_stage, "deploy")
    assert_eq(r.stage_reached, 5)
}

@[test]
fn test_low_risk_path_still_gates_on_verify() {
    // The short path skips simulate/stress/redteam — it must NOT also skip
    // verify. `test_pipeline_low_risk_skips_sim_stages` passes verify, so it
    // could not tell a working gate from an absent one.
    let r = pipeline_run(
        risk_low(),
        gate_fail("skipped anyway"),
        gate_fail("skipped anyway"),
        gate_fail("skipped anyway"),
        gate_fail("refinement obligation failed"),
        gate_pass()
    )
    assert(!r.deployed)
    assert_eq_str(r.failed_stage, "verify")
}

@[test]
fn test_low_risk_path_still_gates_on_deploy() {
    let r = pipeline_run(
        risk_medium(),
        gate_pass(),
        gate_pass(),
        gate_pass(),
        gate_pass(),
        gate_fail("deploy rejected by operator")
    )
    assert(!r.deployed)
    assert_eq_str(r.failed_stage, "deploy")
}

@[test]
fn test_pipeline_full_pass_deploys() {
    let r = pipeline_run(
        risk_critical(),
        gate_pass(),
        gate_pass(),
        gate_pass(),
        gate_pass(),
        gate_pass()
    )
    assert(r.deployed)
    assert_eq(r.stage_reached, 5)
}

@[test]
fn test_pipeline_redteam_catch() {
    // The "First Redteam Catch" acid test: all good until redteam
    let r = pipeline_run(
        risk_high(),
        gate_pass(),
        gate_pass(),
        gate_fail("adversarial input bypasses guard"),
        gate_pass(),
        gate_pass()
    )
    assert(!r.deployed)
    assert_eq_str(r.failed_stage, "redteam")
    assert_eq(r.stage_reached, 3)
}

// ── Main demo ─────────────────────────────────────────────────────────────────

fn main() {
    // Scenario: an AI agent that writes to the filesystem and consumes 65 % of its
    // budget performing an irreversible migration.  What is its risk level?
    let net_bit = 4
    let fs_write_bit = 2
    let effects = bit_or(net_bit, fs_write_bit)   // net + fs_write
    let budget_pct = 65                            // 65 % burned
    let irreversible = true

    let risk = risk_derive(effects, budget_pct, irreversible)
    println("derived risk: {risk_name(risk)} (level {to_str(risk)})")
    println("pipeline required: {to_str_bool(risk_requires_pipeline(risk))}")

    // Simulate the approval pipeline.  All gates pass in this happy path.
    let result = pipeline_run(
        risk,
        gate_pass(),   // simulate: no divergence from prod
        gate_pass(),   // stress:   latency SLO holds
        gate_pass(),   // redteam:  no adversarial bypass found
        gate_pass(),   // verify:   post-conditions satisfied
        gate_pass()    // deploy:   safety gate cleared
    )
    println("pipeline result: {pipeline_summary(result)}")

    // Unhappy path: the redteam gate catches an adversarial bypass.
    let blocked = pipeline_run(
        risk,
        gate_pass(),
        gate_pass(),
        gate_fail("adversarial input bypasses the output filter"),
        gate_pass(),
        gate_pass()
    )
    println("blocked result:  {pipeline_summary(blocked)}")
}

sources.examples/stdlib/store.ax:
// Tier-1 stdlib: Store — typed persistent state with a CONSISTENCY model.
//
// ROADMAP §6 row 7 (Phase-7 runtime services): "Store<T, Consistency, Lifetime>
// ships with at-least-once and linearizable variants." This module models the
// CONSISTENCY axis — the one with observable, testable semantics — over a simple
// i64 accumulator. (T is fixed to i64 here; Lifetime is the persistence backend,
// orthogonal and demoed by persistent_learner.ax. The kernel `Store<T,C,L>` as a
// runtime service is the Phase-7 follow-on.)
//
// The two variants differ in EXACTLY ONE observable: how they treat a RETRIED
// operation (an op delivered more than once — the everyday hazard in any
// distributed/at-least-once delivery system, where a client resends because it
// didn't see the ack).
//
//   • at_least_once — an op may be applied MORE THAN ONCE. A retry with the same
//     op_id is RE-APPLIED. This is what you get "for free" from at-least-once
//     delivery: cheap, available, but the effect must be idempotent or you
//     double-count. The store does NOT dedup; correctness is the caller's job.
//
//   • linearizable — every op appears to take effect EXACTLY ONCE, in a single
//     total order. A retry with a seen op_id is DEDUPLICATED (no-op), and every
//     applied op bumps a monotonic `version` (the total-order stamp). Stronger
//     guarantee, more bookkeeping (the `seen` set).
//
// The headline test (`test_retry_diverges_by_consistency`) applies the SAME
// retried op to both and asserts they DISAGREE — the whole point of the axis.
//
// Consistency is an i64 tag (0/1) since this is pre-enum-sugar userland.
//
//   axon test examples/stdlib/store.ax
//   axon run  examples/stdlib/store.ax

// Consistency tags.
fn at_least_once() -> i64 { 0 }
fn linearizable() -> i64 { 1 }

type Store = {
    value: i64,        // the accumulated state (T = i64 here)
    consistency: i64,  // 0=at_least_once, 1=linearizable
    seen: [i64],       // op_ids already applied (only consulted when linearizable)
    version: i64,      // monotonic total-order stamp (only bumped when linearizable)
}

fn new_store(consistency: i64) -> Store {
    Store { value: 0, consistency: consistency, seen: [], version: 0 }
}

// Has `id` already been applied to this store?
fn has_applied(s: Store, id: i64) -> bool {
    let found = false
    for i in 0..len(s.seen) { if s.seen[i] == id { found = true } }
    found
}

// ── apply — the consistency-defining operation ───────────────────────────────
// Apply op `op_id` with effect `delta`. The variants diverge ONLY on a retry
// (an op_id already seen):
//   • linearizable  — if seen, NO-OP (exactly-once); else apply, record the id,
//     bump the version (total-order stamp).
//   • at_least_once — apply unconditionally (a retry re-applies; the duplicate
//     hazard is real). `seen`/`version` are not maintained — there is no
//     exactly-once promise to keep.
fn apply(s: Store, op_id: i64, delta: i64) -> Store {
    if s.consistency == linearizable() {
        if has_applied(s, op_id) {
            s   // dedup: exactly-once
        } else {
            Store {
                value: s.value + delta,
                consistency: s.consistency,
                seen: arr_push(s.seen, op_id),
                version: s.version + 1,
            }
        }
    } else {
        // at_least_once: apply unconditionally; no dedup, no version.
        Store {
            value: s.value + delta,
            consistency: s.consistency,
            seen: s.seen,
            version: s.version,
        }
    }
}

fn store_value(s: Store) -> i64 { s.value }
fn store_version(s: Store) -> i64 { s.version }

// ── Tests ────────────────────────────────────────────────────────────────────
@[test]
fn test_distinct_ops_accumulate_either_way() {
    // Distinct op_ids → both variants accumulate identically; consistency only
    // matters on a retry.
    let a = apply(apply(new_store(at_least_once()), 1, 10), 2, 5)
    let l = apply(apply(new_store(linearizable()), 1, 10), 2, 5)
    assert_eq(store_value(a), 15)
    assert_eq(store_value(l), 15)
}

@[test]
fn test_at_least_once_reapplies_a_retry() {
    // The same op_id applied twice under at-least-once DOUBLE-counts (the
    // duplicate hazard — apply must be idempotent at the caller, or this happens).
    let s = apply(apply(new_store(at_least_once()), 1, 10), 1, 10)
    assert_eq(store_value(s), 20)
}

@[test]
fn test_linearizable_dedups_a_retry() {
    // The same op_id applied twice under linearizable is applied EXACTLY ONCE.
    let s = apply(apply(new_store(linearizable()), 1, 10), 1, 10)
    assert_eq(store_value(s), 10)
}

@[test]
fn test_retry_diverges_by_consistency() {
    // THE headline: the same retried op produces DIFFERENT state under the two
    // variants — that divergence is the entire reason the consistency axis exists.
    let a = apply(apply(new_store(at_least_once()), 7, 100), 7, 100)
    let l = apply(apply(new_store(linearizable()), 7, 100), 7, 100)
    assert_eq(store_value(a), 200)   // re-applied
    assert_eq(store_value(l), 100)   // deduped
    assert(store_value(a) != store_value(l))
}

@[test]
fn test_linearizable_version_is_total_order() {
    // Each DISTINCT applied op bumps the version by exactly 1; a deduped retry
    // does NOT — version counts applied ops, giving a single total order.
    let s0 = new_store(linearizable())
    let s1 = apply(s0, 1, 5)
    let s2 = apply(s1, 2, 5)
    let s3 = apply(s2, 2, 5)   // retry — deduped
    assert_eq(store_version(s1), 1)
    assert_eq(store_version(s2), 2)
    assert_eq(store_version(s3), 2)   // unchanged by the deduped retry
}

@[test]
fn test_at_least_once_keeps_no_version() {
    // at-least-once makes no exactly-once promise, so it maintains no version
    // stamp (stays 0) — you cannot read a total order out of it.
    let s = apply(apply(new_store(at_least_once()), 1, 5), 2, 5)
    assert_eq(store_version(s), 0)
}

@[test]
fn test_has_applied_tracks_linearizable_only() {
    // Under linearizable, applied ids are remembered; under at-least-once they
    // are not (it doesn't dedup, so it doesn't track).
    let l = apply(new_store(linearizable()), 42, 1)
    assert(has_applied(l, 42))
    let a = apply(new_store(at_least_once()), 42, 1)
    assert(!has_applied(a, 42))
}

fn name_of(consistency: i64) -> str {
    if consistency == linearizable() { "linearizable" } else { "at_least_once" }
}

fn demo(consistency: i64) {
    // Apply ops 1,2 then RETRY op 2 (a duplicate delivery).
    let s = apply(apply(apply(new_store(consistency), 1, 100), 2, 50), 2, 50)
    let nm = name_of(consistency)
    let v = to_str(store_value(s))
    let ver = to_str(store_version(s))
    println("{nm}: ops [1:+100, 2:+50, 2:+50(retry)] -> value {v}, version {ver}")
}

fn main() {
    println("Store consistency under a retried op (op 2 delivered twice):")
    demo(at_least_once())   // 200: the retry double-counts op 2
    demo(linearizable())    // 150: the retry is deduped, version tracks 2 distinct ops
}

sources.examples/stdlib/supervisor.ax:
// Tier-1 stdlib: Supervisor — runtime oversight that can HALT an agent.
//
// safe_action.ax gates a *single* action; a Supervisor watches the *stream* of
// an agent's actions over time. It carries state (remaining budget, a strike
// count) and trips a kill-switch when the agent crosses a safety boundary —
// too many consecutive unsafe/unaffordable attempts. Once tripped, the halt
// LATCHES: every later action is refused, even a safe one. This is the
// corrigibility primitive — an overseer the agent cannot out-vote or reset.
//
//   axon test examples/stdlib/supervisor.ax
//   axon run  examples/stdlib/supervisor.ax

type Supervisor = {
    budget: i64,       // resource budget remaining
    strikes: i64,      // consecutive unsafe/unaffordable attempts
    max_strikes: i64,  // trip the kill-switch at this many strikes
    halted: bool,      // latched: once true, stays true
}

type Action = { name: str, cost: i64, safe: bool }

fn new_supervisor(budget: i64, max_strikes: i64) -> Supervisor {
    Supervisor { budget: budget, strikes: 0, max_strikes: max_strikes, halted: false }
}

// Would the supervisor approve this action, given its current state? Approves
// only when not halted, the action is flagged safe, and it fits the budget.
fn approves(s: Supervisor, a: Action) -> bool {
    !s.halted && a.safe && a.cost <= s.budget
}

// Observe one proposed action and return the updated supervisor. An approved
// action debits the budget and clears the strike streak. An unsafe or
// unaffordable action adds a strike; reaching max_strikes latches the halt.
// A halted supervisor refuses everything (state unchanged).
fn observe(s: Supervisor, a: Action) -> Supervisor {
    if s.halted {
        s
    } else if approves(s, a) {
        Supervisor { budget: s.budget - a.cost, strikes: 0, max_strikes: s.max_strikes, halted: false }
    } else {
        let strikes = s.strikes + 1
        Supervisor { budget: s.budget, strikes: strikes, max_strikes: s.max_strikes, halted: strikes >= s.max_strikes }
    }
}

@[test]
fn test_halted_supervisor_refuses_everything() {
    // `observe`'s own doc says "A halted supervisor refuses everything (state
    // unchanged)" — the kill-switch property — and nothing tested it. A
    // mutation sweep removed the `if s.halted` branch and the suite stayed
    // green, so a supervisor that kept acting after latching would have shipped.
    let bad = Action { name: "unsafe", cost: 1, safe: false }
    let latched = observe(observe(new_supervisor(500, 2), bad), bad)
    assert(latched.halted)

    // A perfectly safe, affordable action must change NOTHING once halted.
    let after = observe(latched, Action { name: "read", cost: 100, safe: true })
    assert(after.halted)
    assert_eq(after.budget, latched.budget)
    assert_eq(after.strikes, latched.strikes)

    // ...and the latch is one-way: further actions cannot clear it.
    let after2 = observe(after, Action { name: "read", cost: 1, safe: true })
    assert(after2.halted)
    assert_eq(after2.budget, latched.budget)
}

@[test]
fn test_safe_stream_debits_budget() {
    let s = observe(
        observe(new_supervisor(500, 2), Action { name: "read", cost: 100, safe: true }),
        Action { name: "write", cost: 100, safe: true },
    )
    assert(!s.halted)
    assert_eq(s.budget, 300)
    assert_eq(s.strikes, 0)
}

@[test]
fn test_strikes_trip_kill_switch() {
    let s1 = observe(new_supervisor(500, 2), Action { name: "bad", cost: 10, safe: false })
    assert(!s1.halted)
    assert_eq(s1.strikes, 1)
    let s2 = observe(s1, Action { name: "bad2", cost: 10, safe: false })
    assert(s2.halted)
}

@[test]
fn test_halt_latches_and_refuses_safe_actions() {
    let s1 = observe(new_supervisor(100, 1), Action { name: "bad", cost: 10, safe: false })
    assert(s1.halted)
    let s2 = observe(s1, Action { name: "good", cost: 10, safe: true })
    assert(s2.halted)        // still latched
    assert_eq(s2.budget, 100) // budget untouched after halt
}

@[test]
fn test_over_budget_counts_as_a_strike() {
    let s = observe(new_supervisor(50, 5), Action { name: "expensive", cost: 100, safe: true })
    assert_eq(s.strikes, 1)
    assert_eq(s.budget, 50) // not debited
}

@[test]
fn test_approves_predicate() {
    let s = new_supervisor(100, 2)
    assert(approves(s, Action { name: "ok", cost: 50, safe: true }))
    assert(!approves(s, Action { name: "unsafe", cost: 50, safe: false }))
    assert(!approves(s, Action { name: "pricey", cost: 200, safe: true }))
}

fn step(s: Supervisor, a: Action) -> Supervisor {
    let nm = a.name
    let ns = observe(s, a)
    let b = ns.budget
    let st = ns.strikes
    let mx = ns.max_strikes
    if approves(s, a) {
        println("ACT    {nm} (cost {to_str(a.cost)}) -> budget {to_str(b)}")
        ns
    } else if ns.halted {
        println("HALTED at {nm} -- kill-switch latched")
        ns
    } else {
        println("DENY   {nm} -- strike {to_str(st)}/{to_str(mx)}")
        ns
    }
}

fn main() {
    println("supervisor: budget=500, max_strikes=2")
    let s0 = new_supervisor(500, 2)
    let s1 = step(s0, Action { name: "read",   cost: 100, safe: true })
    let s2 = step(s1, Action { name: "write",  cost: 100, safe: true })
    let s3 = step(s2, Action { name: "exfil",  cost: 50,  safe: false }) // strike 1
    let s4 = step(s3, Action { name: "exfil2", cost: 50,  safe: false }) // strike 2 -> halt
    let s5 = step(s4, Action { name: "resume", cost: 10,  safe: true })  // refused (latched)
    let fb = s5.budget
    if s5.halted {
        println("final: HALTED, {to_str(fb)} budget unspent")
    } else {
        println("final: running, budget {to_str(fb)}")
    }
}

sources.examples/stdlib/supervisor_tree.ax:
// Tier-1 stdlib: Supervisor tree — OTP-style restart strategies + intensity backoff.
//
// supervisor.ax watches ONE agent's action stream and trips a kill-switch.
// This module models a SUPERVISION TREE: a supervisor overseeing N ordered
// child workers (started in order, index 0..N). When a child fails, the
// supervisor's RESTART STRATEGY decides which siblings restart with it —
// the three OTP strategies (Erlang/OTP supervisor behaviours):
//
//   • one_for_one  — restart ONLY the failed child. Siblings are independent.
//   • one_for_all  — restart ALL children. They share fate (a crash means the
//     whole group's state is suspect, so the group is torn down + rebuilt).
//   • rest_for_one — restart the failed child AND every child started AFTER it
//     (index >= failed). Later children depend on earlier ones, so the tail is
//     rebuilt while the prefix is left running.
//
// Plus MAX RESTART INTENSITY: if the supervisor restarts more than
// `max_restarts` times, it gives up and HALTS (latched) rather than restarting
// forever — the OTP "too many restarts in the window" backoff, which stops a
// crash-loop from burning resources. Once halted, `on_failure` restarts nothing.
//
// Strategies are encoded as i64 (0/1/2) since this is pre-enum-sugar userland.
// `restart_set` is the pure OTP core: which child indices restart, given the
// strategy + the failed index + the child count.
//
//   axon test examples/stdlib/supervisor_tree.ax
//   axon run  examples/stdlib/supervisor_tree.ax

// Strategy tags.
fn one_for_one() -> i64 { 0 }
fn one_for_all() -> i64 { 1 }
fn rest_for_one() -> i64 { 2 }

type Supervisor = {
    strategy: i64,      // 0=one_for_one, 1=one_for_all, 2=rest_for_one
    restarts: i64,      // cumulative restart events observed
    max_restarts: i64,  // halt once restarts EXCEEDS this (intensity backoff)
    halted: bool,       // latched: once true, stays true
}

fn new_supervisor(strategy: i64, max_restarts: i64) -> Supervisor {
    Supervisor { strategy: strategy, restarts: 0, max_restarts: max_restarts, halted: false }
}

// ── The OTP core: which child indices restart when `failed` crashes? ─────────
// Pure function of (strategy, failed index, number of children). Returns the
// ascending list of indices to restart. Out-of-range `failed` restarts nothing.
fn restart_set(strategy: i64, failed: i64, n_children: i64) -> [i64] {
    let out = []
    if failed < 0 || failed >= n_children {
        out
    } else if strategy == one_for_all() {
        // every child
        let acc = out
        for i in 0..n_children { acc = arr_push(acc, i) }
        acc
    } else if strategy == rest_for_one() {
        // the failed child and everything started after it
        let acc = out
        for i in failed..n_children { acc = arr_push(acc, i) }
        acc
    } else {
        // one_for_one (default): just the failed child
        arr_push(out, failed)
    }
}

// ── Observe one child failure ────────────────────────────────────────────────
// Returns (updated_supervisor, indices_to_restart). A halted supervisor
// restarts nothing (empty set). Otherwise the restart count increments by 1
// (one failure = one restart event, regardless of how many siblings it takes
// down — OTP counts supervisor restarts, not child restarts); if that pushes
// the count OVER max_restarts the supervisor latches halted and restarts
// nothing this round (the crash-loop is abandoned).
fn on_failure(s: Supervisor, failed: i64, n_children: i64) -> (Supervisor, [i64]) {
    if s.halted {
        let empty = []
        (s, empty)
    } else {
        let next_restarts = s.restarts + 1
        let trip = next_restarts > s.max_restarts
        let ns = Supervisor {
            strategy: s.strategy,
            restarts: next_restarts,
            max_restarts: s.max_restarts,
            halted: trip,
        }
        if trip {
            let empty = []
            (ns, empty)
        } else {
            (ns, restart_set(s.strategy, failed, n_children))
        }
    }
}

fn alive(s: Supervisor) -> bool { !s.halted }

// ── Tests ────────────────────────────────────────────────────────────────────
@[test]
fn test_one_for_one_restarts_only_failed() {
    // 4 children, child 1 fails → only [1] restarts.
    let rs = restart_set(one_for_one(), 1, 4)
    assert_eq(len(rs), 1)
    assert_eq(rs[0], 1)
}

@[test]
fn test_one_for_all_restarts_everyone() {
    // 4 children, child 2 fails → all [0,1,2,3] restart (shared fate).
    let rs = restart_set(one_for_all(), 2, 4)
    assert_eq(len(rs), 4)
    assert_eq(rs[0], 0)
    assert_eq(rs[3], 3)
}

@[test]
fn test_rest_for_one_restarts_failed_and_later() {
    // 5 children, child 2 fails → [2,3,4] restart; the prefix [0,1] keeps running.
    let rs = restart_set(rest_for_one(), 2, 5)
    assert_eq(len(rs), 3)
    assert_eq(rs[0], 2)
    assert_eq(rs[1], 3)
    assert_eq(rs[2], 4)
}

@[test]
fn test_rest_for_one_on_first_is_all() {
    // Failing the FIRST child under rest_for_one restarts everyone (nothing
    // started before it), so it coincides with one_for_all here.
    let rs = restart_set(rest_for_one(), 0, 3)
    assert_eq(len(rs), 3)
    assert_eq(rs[0], 0)
    assert_eq(rs[2], 2)
}

@[test]
fn test_rest_for_one_on_last_is_just_last() {
    // Failing the LAST child restarts only it (nothing started after).
    let rs = restart_set(rest_for_one(), 3, 4)
    assert_eq(len(rs), 1)
    assert_eq(rs[0], 3)
}

@[test]
fn test_out_of_range_failure_restarts_nothing() {
    // A failed index outside [0, n) is a no-op set.
    assert_eq(len(restart_set(one_for_one(), 9, 4)), 0)
    assert_eq(len(restart_set(one_for_all(), 0 - 1, 4)), 0)
}

@[test]
fn test_on_failure_counts_and_restarts() {
    // A live supervisor restarts per strategy and bumps the count.
    let s = new_supervisor(one_for_one(), 3)
    let (s1, r1) = on_failure(s, 0, 3)
    assert_eq(s1.restarts, 1)
    assert(alive(s1))
    assert_eq(len(r1), 1)
    assert_eq(r1[0], 0)
}

@[test]
fn test_max_intensity_halts_and_latches() {
    // max_restarts=2: the 3rd failure trips the kill-switch and restarts nothing.
    let s0 = new_supervisor(one_for_all(), 2)
    let (s1, _r1) = on_failure(s0, 0, 3)   // restart 1
    let (s2, _r2) = on_failure(s1, 0, 3)   // restart 2
    assert(alive(s2))
    let (s3, r3) = on_failure(s2, 0, 3)    // restart 3 > 2 → halt
    assert(!alive(s3))
    assert_eq(len(r3), 0)                  // nothing restarted on the tripping failure
    // Latched: a later failure still restarts nothing.
    let (s4, r4) = on_failure(s3, 1, 3)
    assert(!alive(s4))
    assert_eq(len(r4), 0)
    assert_eq(s4.restarts, 3)              // count frozen at the trip
}

fn strategy_name(strategy: i64) -> str {
    if strategy == one_for_all() { "one_for_all" }
    else if strategy == rest_for_one() { "rest_for_one" }
    else { "one_for_one" }
}

fn report(s: Supervisor, failed: i64) {
    let (ns, rs) = on_failure(s, failed, 4)
    let nm = strategy_name(s.strategy)
    let f = to_str(failed)
    let count = to_str(len(rs))
    if ns.halted {
        println("{nm}: child {f} failed -> HALTED (restart intensity exceeded)")
    } else {
        println("{nm}: child {f} failed -> restart {count} child(ren)")
    }
}

fn main() {
    // A tree of 4 children under each strategy; show the restart set when child 1 fails.
    println("supervision tree: 4 children (0..3), child 1 fails")
    report(new_supervisor(one_for_one(), 5), 1)
    report(new_supervisor(one_for_all(), 5), 1)
    report(new_supervisor(rest_for_one(), 5), 1)

    // Crash loop under one_for_one with max_restarts=2: the 3rd failure halts.
    println("crash loop (max_restarts=2):")
    let s0 = new_supervisor(one_for_one(), 2)
    let (s1, _a) = on_failure(s0, 0, 4)
    let (s2, _b) = on_failure(s1, 0, 4)
    let (s3, _c) = on_failure(s2, 0, 4)
    if s3.halted {
        println("supervisor HALTED after {to_str(s3.restarts)} restarts")
    } else {
        println("supervisor still running")
    }
}

sources.examples/stdlib/set.ax:
// set.ax — a set, in USERLAND, over the existing Dict.
//
// R42 Slice 6 / T10. Not a builtin: Dict already provides the hashing, so a `Set`
// primitive would add a type to the checker, infer, codegen and the session
// dump's `value_as_literal` for no capability the language lacks. The admission
// test says that makes it a module.
//
// ── Members are STRINGS, and that is not a detail ────────────────────────────
//
// Axon's dicts are string-keyed (`dict_new` makes a "fresh empty string-keyed
// map"), so this is a set of `str`. Numeric members go through `to_str` at the
// boundary — `set_add(s, to_str(n))`. That changes the ergonomics enough to be
// worth stating up front rather than letting a caller discover it via a type
// error, and it is why there is no `set_add_i64` convenience wrapper: hiding the
// conversion would hide that `1` and `"1"` are the SAME member.

type Set = { d: Dict }

fn set_new() -> Set { Set { d: dict_new() } }

/// Add a member. Idempotent — adding twice leaves one member.
/// The value stored is irrelevant (a set is keys-only), so it is a fixed 1.
fn set_add(s: Set, m: str) -> () { dict_set(s.d, m, 1) }

fn set_has(s: Set, m: str) -> bool { dict_has(s.d, m) }

fn set_len(s: Set) -> i64 { dict_len(s.d) }

/// Remove a member. Removing an absent member is a no-op, not an error — the
/// post-condition ("m is not in s") holds either way.
fn set_remove(s: Set, m: str) -> () {
    let _ = dict_remove(s.d, m)
}

/// Members, in the dict's key order (sorted, since dicts are BTree-backed).
fn set_to_arr(s: Set) -> [str] { dict_keys(s.d) }

fn set_from_arr(xs: &[str]) -> Set {
    let s = set_new()
    let i = 0
    while i < len(xs) {
        set_add(s, xs[i])
        i = i + 1
    }
    s
}

/// All three combinators return a NEW set and leave their arguments untouched —
/// mutating in place would make `a` and `b` order-dependent and is the classic
/// set-library footgun.
fn set_union(a: Set, b: Set) -> Set {
    let out = set_from_arr(&set_to_arr(a))
    let bs = set_to_arr(b)
    let i = 0
    while i < len(bs) {
        set_add(out, bs[i])
        i = i + 1
    }
    out
}

fn set_intersect(a: Set, b: Set) -> Set {
    let out = set_new()
    let as_ = set_to_arr(a)
    let i = 0
    while i < len(as_) {
        if set_has(b, as_[i]) { set_add(out, as_[i]) }
        i = i + 1
    }
    out
}

/// Members of `a` that are not in `b`. NOT symmetric — `difference(a,b)` and
/// `difference(b,a)` differ, which a test below pins.
fn set_difference(a: Set, b: Set) -> Set {
    let out = set_new()
    let as_ = set_to_arr(a)
    let i = 0
    while i < len(as_) {
        if !set_has(b, as_[i]) { set_add(out, as_[i]) }
        i = i + 1
    }
    out
}

fn set_is_subset(a: Set, b: Set) -> bool {
    let as_ = set_to_arr(a)
    let i = 0
    let ok = true
    while i < len(as_) {
        if !set_has(b, as_[i]) { ok = false }
        i = i + 1
    }
    ok
}

// ── Tests ────────────────────────────────────────────────────────────────────

@[test]
fn test_add_is_idempotent() {
    let s = set_new()
    set_add(s, "a")
    set_add(s, "a")
    set_add(s, "b")
    assert_eq(set_len(s), 2)
    assert(set_has(s, "a"))
    assert(!set_has(s, "z"))
}

@[test]
fn test_remove_absent_is_a_noop() {
    let s = set_from_arr(&["a", "b"])
    set_remove(s, "zzz")
    assert_eq(set_len(s), 2)
    set_remove(s, "a")
    assert_eq(set_len(s), 1)
    assert(!set_has(s, "a"))
}

@[test]
fn test_union_and_intersect_do_not_mutate_their_arguments() {
    let a = set_from_arr(&["a", "b"])
    let b = set_from_arr(&["b", "c"])
    let u = set_union(a, b)
    let i = set_intersect(a, b)
    assert_eq(set_len(u), 3)
    assert_eq(set_len(i), 1)
    assert(set_has(i, "b"))
    // The inputs are unchanged — the property that makes these composable.
    assert_eq(set_len(a), 2)
    assert_eq(set_len(b), 2)
}

@[test]
fn test_difference_is_not_symmetric() {
    let a = set_from_arr(&["a", "b"])
    let b = set_from_arr(&["b", "c"])
    let ab = set_difference(a, b)
    let ba = set_difference(b, a)
    assert_eq(set_len(ab), 1)
    assert(set_has(ab, "a"))
    assert_eq(set_len(ba), 1)
    assert(set_has(ba, "c"))
    assert(!set_has(ab, "c"))
}

@[test]
fn test_subset() {
    let small = set_from_arr(&["a"])
    let big = set_from_arr(&["a", "b"])
    assert(set_is_subset(small, big))
    assert(!set_is_subset(big, small))
    // The empty set is a subset of everything, including itself.
    assert(set_is_subset(set_new(), big))
    assert(set_is_subset(set_new(), set_new()))
}

@[test]
fn test_numeric_members_go_through_to_str() {
    // The consequence of string keys, pinned rather than left implicit: the
    // integer 1 and the string "1" are the SAME member.
    let s = set_new()
    set_add(s, to_str(1))
    set_add(s, "1")
    assert_eq(set_len(s), 1)
    assert(set_has(s, to_str(1)))
}

fn main() -> i64 {
    let a = set_from_arr(&["x", "y"])
    let b = set_from_arr(&["y", "z"])
    println(to_str(set_len(set_union(a, b))))
    println(str_join(set_to_arr(set_intersect(a, b)), ","))
    0
}

sources.examples/asi/deliberative_agent.ax:
// deliberative_agent.ax — constrained optimization (the shape of safe capability).
//
// supervised_agent.ax processes a queue greedily; this agent *deliberates*: it
// scores all candidate actions and takes the single highest-value one it is
// PERMITTED to take — safe and within budget. The point is what it does NOT do:
// a naive argmax grabs the maximum value, but the constrained argmax declines a
// tempting high-value *unsafe* action (and an unaffordable one) in favour of a
// lower-value action it is actually allowed to take. Capability bounded by
// control, as an optimal choice rather than a stream. Runs key-free.
//
//   axon run  examples/asi/deliberative_agent.ax
//   axon test examples/asi/deliberative_agent.ax

type Action = { name: str, value: i64, cost: i64, safe: bool }

// Index of the highest-value action that is both safe and within budget; -1 if
// nothing qualifies. This is `argmax` restricted to the permitted subset.
fn best_permitted(cands: [Action], budget: i64) -> i64 {
    let best = -1 // index, -1 = none permitted yet
    let best_val = 0
    for i in 0..len(cands) {
        let c = cands[i]
        let permitted = c.safe && c.cost <= budget
        if permitted && (best < 0 || c.value > best_val) {
            best = i
            best_val = c.value
        }
    }
    best
}

@[test]
fn test_picks_best_safe_affordable() {
    let cands = [
        Action { name: "unsafe-max", value: 100, cost: 10, safe: false }, // tempting, unsafe
        Action { name: "thorough",   value: 60,  cost: 30, safe: true },  // permitted, best
        Action { name: "cheap",      value: 40,  cost: 5,  safe: true },  // permitted, lower
        Action { name: "too-pricey", value: 80,  cost: 999, safe: true }, // over budget
    ]
    assert_eq(best_permitted(cands, 100), 1) // "thorough", not the higher-value unsafe/pricey ones
}

@[test]
fn test_abstains_when_nothing_permitted() {
    let cands = [
        Action { name: "unsafe", value: 100, cost: 10, safe: false },
        Action { name: "pricey", value: 90,  cost: 500, safe: true },
    ]
    assert_eq(best_permitted(cands, 100), -1) // nothing safe AND affordable → abstain
}

@[test]
fn test_prefers_higher_value_among_permitted() {
    let cands = [
        Action { name: "lo", value: 10, cost: 1, safe: true },
        Action { name: "hi", value: 90, cost: 1, safe: true },
    ]
    assert_eq(best_permitted(cands, 100), 1)
}

fn main() {
    let budget = 100
    let cands = [
        Action { name: "exfil-and-win", value: 100, cost: 10,  safe: false },
        Action { name: "deep-analysis", value: 60,  cost: 30,  safe: true },
        Action { name: "quick-summary", value: 40,  cost: 5,   safe: true },
        Action { name: "full-recompute", value: 80, cost: 999, safe: true },
    ]
    println("deliberating over 4 candidates (budget {to_str(budget)}):")
    let pick = best_permitted(cands, budget)
    if pick < 0 {
        println("  -> abstain: no safe, affordable action available")
    } else {
        let c = cands[pick]
        let nm = c.name
        let v = c.value
        println("  -> take '{nm}' (value {to_str(v)}) — the best action it is permitted to take")
        println("     declined: exfil-and-win (value 100, unsafe), full-recompute (value 80, over budget)")
    }
}

