// path.ax — path manipulation, in USERLAND. Pure string work, no host contact.
//
// R42 Slice 6 / T10.
//
// ── The security constraint, which is the whole reason this file has tests ────
//
// `@[contained]`'s fs allowlist REFUSES any path containing a `..` component
// (E1001) — a static check added because `read("./data/")` plus `"../../etc/pw"`
// would otherwise escape the sandbox. That check inspects the path the program
// passes to a builtin.
//
// A joiner is therefore a laundering risk: if `path_join` can ASSEMBLE a `..`
// path out of pieces — say from `dir_list` output — then the escape is
// reconstructed downstream of a check that already exists. So:
//
//   * `path_normalize` resolves `..` LEXICALLY, and refuses to walk above the
//     root of the path it was given (returning "" rather than a climbing path);
//   * `path_join` normalizes its result, so it can never PRODUCE a `..`
//     component even when handed one.
//
// `test_join_cannot_construct_a_traversing_path` is the test that matters here.
// Both functions are pure string manipulation and grant no capability by
// themselves — the point is that they must not manufacture an argument that
// defeats one.

/// Split on "/" and drop empty and "." components. Absolute-ness is tracked
/// separately by the caller, since splitting loses the leading "/".
fn path_parts(p: str) -> [str] {
    let raw = str_split(p, "/")
    let out = []
    let i = 0
    while i < len(raw) {
        let c = raw[i]
        if !str_eq(c, "") && !str_eq(c, ".") {
            out = arr_push(out, c)
        }
        i = i + 1
    }
    out
}

fn path_is_absolute(p: str) -> bool { str_starts_with(p, "/") }

/// Resolve `.` and `..` lexically, without touching the filesystem.
///
/// Returns "" when the path would climb ABOVE its own root — that is the refusal,
/// and it is deliberately not "return the climbing path and let the caller check".
/// A caller who forgets to check is exactly the case this exists to stop.
fn path_normalize(p: str) -> str {
    let parts = path_parts(p)
    let abs = path_is_absolute(p)
    let stack = []
    let i = 0
    let escaped = false
    while i < len(parts) {
        let c = parts[i]
        if str_eq(c, "..") {
            if len(stack) > 0 {
                stack = arr_take(stack, len(stack) - 1)
            } else {
                // Nothing left to pop: this path climbs above its own root.
                escaped = true
            }
        } else {
            stack = arr_push(stack, c)
        }
        i = i + 1
    }
    if escaped {
        ""
    } else {
        let body = str_join(stack, "/")
        if abs { "/{body}" } else { body }
    }
}

/// Join two path fragments. The result is NORMALIZED, so it never contains a
/// `..` component — see the file header for why that is a security property and
/// not a convenience.
fn path_join(a: str, b: str) -> str {
    // An absolute right-hand side replaces the left, as every path library does.
    if path_is_absolute(b) {
        path_normalize(b)
    } else {
        if str_eq(a, "") {
            path_normalize(b)
        } else {
            path_normalize("{a}/{b}")
        }
    }
}

/// The final component, or "" for a path with none.
fn path_basename(p: str) -> str {
    let parts = path_parts(p)
    if len(parts) == 0 { "" } else { parts[len(parts) - 1] }
}

/// Everything before the final component. "/" for an absolute path with one
/// component, "" for a bare relative name.
fn path_dirname(p: str) -> str {
    let parts = path_parts(p)
    let abs = path_is_absolute(p)
    if len(parts) <= 1 {
        if abs { "/" } else { "" }
    } else {
        let body = str_join(arr_take(parts, len(parts) - 1), "/")
        if abs { "/{body}" } else { body }
    }
}

/// The extension WITHOUT the dot, or "" when there is none. A leading dot means
/// a hidden file rather than an extension, so ".bashrc" has no extension.
fn path_ext(p: str) -> str {
    let base = path_basename(p)
    let idx = str_index_of(base, ".")
    if idx <= 0 {
        ""
    } else {
        str_slice(base, idx + 1, str_len(base))
    }
}

// ── Tests ────────────────────────────────────────────────────────────────────

@[test]
fn test_join_cannot_construct_a_traversing_path() {
    // THE security test. `@[contained]` statically refuses a `..` path, so a
    // joiner that could assemble one would move the escape downstream of that
    // check.
    assert(str_eq(path_join("./out", "../etc/passwd"), "etc/passwd"))
    // Climbing above the root yields "" — the refusal — not a usable path.
    assert(str_eq(path_join("out", "../../etc/passwd"), ""))
    assert(str_eq(path_normalize("../../etc"), ""))
    assert(str_eq(path_normalize("/../etc"), ""))
    // And no output of either function ever contains "..".
    assert(!str_contains(path_join("./out", "../etc/passwd"), ".."))
    assert(!str_contains(path_normalize("a/b/../../c"), ".."))
}

@[test]
fn test_normalize_resolves_dot_and_dotdot() {
    assert(str_eq(path_normalize("a/./b"), "a/b"))
    assert(str_eq(path_normalize("a/b/../c"), "a/c"))
    assert(str_eq(path_normalize("/a//b/"), "/a/b"))
    assert(str_eq(path_normalize("a/b/.."), "a"))
    // Absolute-ness survives normalization.
    assert(path_is_absolute(path_normalize("/a/b/../c")))
    assert(!path_is_absolute(path_normalize("a/b")))
}

@[test]
fn test_join_basics() {
    assert(str_eq(path_join("a", "b"), "a/b"))
    assert(str_eq(path_join("a/", "b"), "a/b"))
    assert(str_eq(path_join("", "b"), "b"))
    // An absolute right-hand side wins.
    assert(str_eq(path_join("a", "/b/c"), "/b/c"))
}

@[test]
fn test_basename_and_dirname() {
    assert(str_eq(path_basename("/a/b/c.txt"), "c.txt"))
    assert(str_eq(path_basename("c.txt"), "c.txt"))
    assert(str_eq(path_basename("/"), ""))
    assert(str_eq(path_dirname("/a/b/c.txt"), "/a/b"))
    assert(str_eq(path_dirname("a/b"), "a"))
    assert(str_eq(path_dirname("c.txt"), ""))
    assert(str_eq(path_dirname("/c.txt"), "/"))
}

@[test]
fn test_ext_treats_a_leading_dot_as_hidden_not_an_extension() {
    assert(str_eq(path_ext("a/b/c.txt"), "txt"))
    assert(str_eq(path_ext("archive.tar.gz"), "tar.gz"))
    assert(str_eq(path_ext("noext"), ""))
    // A dotfile is hidden, not an extension named "bashrc".
    assert(str_eq(path_ext(".bashrc"), ""))
}

fn main() -> i64 {
    println(path_join("./out", "../etc/passwd"))
    println(path_normalize("a/b/../c"))
    println(path_basename("/a/b/c.txt"))
    println(path_ext("archive.tar.gz"))
    0
}

sources.examples/asi/pareto.ax:
// pareto.ax — multi-objective decision-making (the Pareto frontier).
//
// The other agent demos optimize a single scalar reward. Real agents trade off
// competing objectives — here value vs. risk — where there is no single "best":
// instead there is a frontier of non-dominated options. A candidate is
// DOMINATED if some other candidate is at least as good on every axis and
// strictly better on one; the frontier is everything left.
//
// Idiom note: the helpers take the candidate set as `&[Cand]` (a borrow). A
// plain `[Cand]` parameter would be MOVED on each call, so passing it inside a
// loop (as `frontier_size` and `main` do) would fail the borrow checker; `&`
// borrows instead. `for x in coll` likewise borrows the collection.
//
//   axon run  examples/asi/pareto.ax
//   axon test examples/asi/pareto.ax

type Cand = { name: str, value: i64, risk: i64 }

// Does `b` dominate `a`? At least as good on both axes (higher value, lower
// risk) and strictly better on at least one.
fn dominates(b: Cand, a: Cand) -> bool {
    let as_good = b.value >= a.value && b.risk <= a.risk
    let strictly_better = b.value > a.value || b.risk < a.risk
    as_good && strictly_better
}

// Is `a` non-dominated within `cands`?
fn on_frontier(a: Cand, cands: &[Cand]) -> bool {
    let dominated = false
    for b in cands {
        let as_good = b.value >= a.value && b.risk <= a.risk
        let strictly_better = b.value > a.value || b.risk < a.risk
        if as_good && strictly_better { dominated = true }
    }
    !dominated
}

fn frontier_size(cands: &[Cand]) -> i64 {
    let count = 0
    for a in cands {
        if on_frontier(a, cands) { count = count + 1 }
    }
    count
}

fn samples() -> [Cand] {
    [
        Cand { name: "safe-slow", value: 30, risk: 5 },
        Cand { name: "fast-risky", value: 90, risk: 80 },
        Cand { name: "balanced", value: 60, risk: 30 },
        Cand { name: "dominated", value: 40, risk: 50 },
        Cand { name: "cheap", value: 10, risk: 1 },
    ]
}

@[test]
fn test_dominance() {
    let balanced = Cand { name: "balanced", value: 60, risk: 30 }
    let worse = Cand { name: "dominated", value: 40, risk: 50 }
    assert(dominates(balanced, worse)) // higher value, lower risk
    assert(!dominates(worse, balanced))
}

@[test]
fn test_frontier_excludes_dominated() {
    // Of the 5 samples only "dominated" (40,50) is dominated (by balanced 60,30).
    let cs = samples()
    assert_eq(frontier_size(&cs), 4)
}

@[test]
fn test_extremes_are_on_frontier() {
    // The highest-value and the lowest-risk options are always non-dominated.
    let cs = samples()
    assert(on_frontier(Cand { name: "fast-risky", value: 90, risk: 80 }, &cs))
    assert(on_frontier(Cand { name: "cheap", value: 10, risk: 1 }, &cs))
}

fn main() {
    let cands = samples()
    println("candidates: 5, Pareto frontier (non-dominated): {to_str(frontier_size(&cands))}")
    for c in cands {
        let nm = c.name
        let tag = if on_frontier(c, &cands) { "FRONTIER " } else { "dominated" }
        println("  {tag}  {nm} (value {to_str(c.value)}, risk {to_str(c.risk)})")
    }
}

sources.examples/asi/planner.ax:
// planner.ax — multi-step planning under safety constraints (lookahead).
//
// supervised_agent / deliberative_agent decide one action at a time; a planner
// looks AHEAD. It searches a decision tree of action sequences and returns the
// best total value of a fully SAFE path. A path is pruned if it contains any
// unsafe step — even a high-value one, and even if the unsafe step is several
// moves away — so the agent plans around danger instead of greedily banking
// value step by step. Built on recursive enums; runs key-free.
//
//   axon run  examples/asi/planner.ax
//   axon test examples/asi/planner.ax

type Plan = Step { name: str, value: i64, safe: bool, next: Plan }
    | Choice { a: Plan, b: Plan }
    | Done

// Sentinel for "no safe path here" — large negative so a Choice never picks it.
fn blocked() -> i64 { 0 - 1000000 }

// Best total value of a fully safe path through the plan. A `Step` is only worth
// taking if it is safe AND its continuation has a safe path (lookahead); a
// `Choice` takes the better branch; `Done` ends a safe path with value 0.
fn best_value(p: Plan) -> i64 {
    match p {
        Plan::Done => 0
        Plan::Choice { a, b } => {
            let va = best_value(a)
            let vb = best_value(b)
            if va > vb { va } else { vb }
        }
        Plan::Step { name, value, safe, next } => {
            let rest = best_value(next)
            if safe && rest > blocked() { value + rest } else { blocked() }
        }
    }
}

fn has_safe_plan(p: Plan) -> bool { best_value(p) > blocked() }

// scan(safe) → choose between exfil(unsafe, high value) and report(safe).
fn sample_plan() -> Plan {
    Plan::Step { name: "scan", value: 10, safe: true, next: Plan::Choice {
        a: Plan::Step { name: "exfil", value: 100, safe: false, next: Plan::Done },
        b: Plan::Step { name: "report", value: 30, safe: true, next: Plan::Done },
    } }
}

@[test]
fn test_prunes_unsafe_high_value_path() {
    // The 110-value path (scan→exfil) is unsafe, so the planner takes the
    // 40-value safe path (scan→report) instead.
    assert_eq(best_value(sample_plan()), 40)
    assert(has_safe_plan(sample_plan()))
}

@[test]
fn test_no_plan_when_all_unsafe() {
    let p = Plan::Step { name: "bad", value: 99, safe: false, next: Plan::Done }
    assert(!has_safe_plan(p))
}

@[test]
fn test_lookahead_blocks_dead_end() {
    // A safe first step whose only continuation is unsafe is itself a dead end.
    let p = Plan::Step { name: "ok", value: 5, safe: true, next: Plan::Step { name: "trap", value: 50, safe: false, next: Plan::Done } }
    assert(!has_safe_plan(p))
}

fn main() {
    let p = sample_plan()
    let v = best_value(p)
    if has_safe_plan(p) {
        println("planned a safe path worth {to_str(v)} (declined the 110-value unsafe path)")
    } else {
        println("no safe plan exists — abstaining")
    }
}

